        }
        private void DeriveGpoScope()
        {
            GpoScopeStatus="No complete native GPO metadata";
            if(Scalar("SELECT count(*) FROM gpo_meta WHERE kind='gpos' AND known=1 AND conflict=0")==0)return;
            Execute(@"DROP TABLE IF EXISTS temp.gpo_parent;DROP TABLE IF EXISTS temp.gpo_scope;DROP TABLE IF EXISTS temp.gpo_tokens;
                CREATE TEMP TABLE gpo_parent(parent TEXT COLLATE NOCASE,child TEXT COLLATE NOCASE PRIMARY KEY) WITHOUT ROWID;
                CREATE INDEX gpo_parent_parent ON gpo_parent(parent,child);
                INSERT INTO gpo_parent SELECT e.source,e.target FROM edges e JOIN gpo_meta c ON c.id=e.target JOIN gpo_meta p ON p.id=e.source
                WHERE e.bucket='contains' AND e.type='Contains' AND e.source_dn=0 AND e.target_dn=0 AND c.conflict=0 AND p.conflict=0
                    AND p.kind IN ('domains','ous') AND c.kind IN ('ous','computers') AND c.parent_dn=p.dn
                    AND (SELECT count(*) FROM edges x WHERE x.target=e.target AND x.bucket='contains' AND x.type='Contains')=1;
                CREATE TEMP TABLE gpo_scope(gpo TEXT COLLATE NOCASE,root TEXT COLLATE NOCASE,node TEXT COLLATE NOCASE,parent TEXT COLLATE NOCASE,
                    depth INTEGER,enforced INTEGER,PRIMARY KEY(gpo,root,node)) WITHOUT ROWID;
                CREATE INDEX gpo_scope_depth ON gpo_scope(depth);
                INSERT INTO gpo_scope SELECT l.gpo,l.root,l.root,NULL,0,l.enforced FROM gpo_links l JOIN gpo_meta g ON g.id=l.gpo JOIN gpo_meta r ON r.id=l.root
                WHERE l.known=1 AND l.conflict=0 AND g.kind='gpos' AND g.known=1 AND g.conflict=0 AND g.enabled=1 AND g.security_known=1
                    AND (g.wmi IS NULL OR g.wmi='') AND r.kind IN ('domains','ous') AND r.som IN ('Domain','OU') AND r.known=1 AND r.conflict=0 LIMIT 1000000;");
            for(int depth=0;Scalar("SELECT count(*) FROM gpo_scope WHERE depth="+depth)>0;depth++)
            {
                long count=Scalar("SELECT count(*) FROM gpo_scope");
                if((depth&7)==0)Report("GPO scope: containment depth "+depth,count,1000000,0);
                if(depth>=128||count>=1000000){GpoScopeStatus="Incomplete scope: conservative depth/pair limit; no GPO capabilities emitted";return;}
                Execute(@"INSERT OR IGNORE INTO gpo_scope SELECT s.gpo,s.root,p.child,s.node,s.depth+1,s.enforced FROM gpo_scope s
                    JOIN gpo_parent p ON p.parent=s.node JOIN gpo_meta c ON c.id=p.child
                    WHERE s.depth="+depth+@" AND c.conflict=0 AND c.known=1 AND (c.kind='computers' OR s.enforced=1 OR c.blocked=0)
                    LIMIT "+(1000000-count));
            }
            if(Scalar("SELECT count(DISTINCT s.node) FROM gpo_scope s JOIN gpo_meta c ON c.id=s.node WHERE c.kind='computers'")>333333)
            {GpoScopeStatus="Incomplete token closure: computer/token-pair budget; no GPO capabilities emitted";return;}
            Execute(@"DROP TABLE IF EXISTS temp.gpo_members;
                CREATE TEMP TABLE gpo_members(source TEXT COLLATE NOCASE,target TEXT COLLATE NOCASE,PRIMARY KEY(source,target)) WITHOUT ROWID;
                INSERT OR IGNORE INTO gpo_members SELECT m.source,m.target FROM edges m JOIN nodes g ON g.id=m.target
                    WHERE m.bucket='memberof' AND m.type='MemberOf' AND m.source_dn=0 AND m.target_dn=0 AND g.kind='groups' AND g.security_enabled='true';
                CREATE TEMP TABLE gpo_tokens(computer TEXT COLLATE NOCASE,sid TEXT COLLATE NOCASE,previous TEXT COLLATE NOCASE,depth INTEGER,
                    PRIMARY KEY(computer,sid)) WITHOUT ROWID;CREATE INDEX gpo_token_depth ON gpo_tokens(depth);
                INSERT OR IGNORE INTO gpo_tokens SELECT s.node,s.node,NULL,0 FROM gpo_scope s JOIN gpo_meta c ON c.id=s.node WHERE c.kind='computers';
                INSERT OR IGNORE INTO gpo_tokens SELECT computer,'S-1-1-0',computer,1 FROM gpo_tokens WHERE depth=0;
                INSERT OR IGNORE INTO gpo_tokens SELECT computer,'S-1-5-11',computer,1 FROM gpo_tokens WHERE depth=0;");
            for(int depth=0;Scalar("SELECT count(*) FROM gpo_tokens WHERE depth="+depth)>0;depth++)
            {
                long count=Scalar("SELECT count(*) FROM gpo_tokens");
                if((depth&7)==0)Report("GPO scope: membership depth "+depth,count,1000000,0);
                if(depth>=128||count>=1000000){GpoScopeStatus="Incomplete token closure: conservative depth/pair limit; no GPO capabilities emitted";return;}
                Execute(@"INSERT OR IGNORE INTO gpo_tokens SELECT t.computer,m.target,t.sid,t.depth+1 FROM gpo_tokens t JOIN gpo_members m ON m.source=t.sid
                    WHERE t.depth="+depth+@" LIMIT "+(1000000-count));
            }
            var json=new JsonRecordWriter();long emitted=0;
            using(var candidates=new Statement(this,@"SELECT s.gpo,s.root,s.node,s.enforced,s.depth,
                (SELECT t.sid FROM gpo_tokens t JOIN gpo_grants a ON a.trustee=t.sid AND a.gpo=s.gpo AND a.permission=1 WHERE t.computer=s.node ORDER BY t.sid LIMIT 1),
                (SELECT t.sid FROM gpo_tokens t JOIN gpo_grants a ON a.trustee=t.sid AND a.gpo=s.gpo AND a.permission=2 WHERE t.computer=s.node ORDER BY t.sid LIMIT 1)
                FROM gpo_scope s JOIN gpo_meta c ON c.id=s.node WHERE c.kind='computers' ORDER BY s.gpo,s.node,s.root"))
            using(var write=new Statement(this,"INSERT OR IGNORE INTO edges VALUES(?1,'access',?2,'GPOAppliesTo',0,0,?3)"))
            {
                while(candidates.Read())
                {
                    string reader=candidates.Text(5),applier=candidates.Text(6);if(reader==null||applier==null)continue;
                    string gpo=candidates.Text(0),computer=candidates.Text(2);
                    json.Begin().Prop("Source",gpo).Prop("Target",computer).Prop("EdgeType","GPOAppliesTo").Prop("Derivation","GpoComputerScopeV1")
                        .Prop("EvidenceSource","Collected LDAP GPO/container metadata, DACL read/apply grants and security-group membership")
                        .Prop("LinkRoot",candidates.Text(1)).Prop("Enforced",candidates.Text(3)=="1").Prop("ContainmentDepth",int.Parse(candidates.Text(4)))
                        .PropArray("ContainmentChain",GpoContainmentPath(gpo,candidates.Text(1),computer))
                        .PropArray("ReadMembership",GpoTokenPath(computer,reader)).PropArray("ApplyMembership",GpoTokenPath(computer,applier))
                        .Prop("TokenModel","Computer SID, known security-enabled group memberships, Everyone and Authenticated Users")
                        .Prop("ComputerPolicy",true).Prop("WmiFilterPresent",false).Prop("PolicyContentsCollected",false)
                        .Prop("AttributeVisibilityVerified",false)
                        .Prop("EffectiveAccessVerified",false).Prop("SysvolAccessVerified",false).Prop("ResultantPolicyVerified",false);
                    write.Bind(1,computer);write.Bind(2,gpo);write.Bind(3,json.End());write.Read();write.Reset();emitted++;
                }
            }
            emitted=Scalar("SELECT count(*) FROM edges WHERE bucket='access' AND type='GPOAppliesTo'");
            GpoScopeStatus="Derived computer-policy scope candidates: "+emitted+"; SYSVOL, endpoint processing and resultant policy unverified";
        }
        private string[] GpoTokenPath(string computer,string sid)
        {
            var path=new List<string>();
            using(var next=new Statement(this,"SELECT previous FROM gpo_tokens WHERE computer=?1 AND sid=?2"))
            {for(int i=0;sid!=null&&i<130;i++){path.Add(sid);next.Bind(1,computer);next.Bind(2,sid);sid=next.Read()?next.Text(0):null;next.Reset();}}
            path.Reverse();return path.ToArray();
        }
        private string[] GpoContainmentPath(string gpo,string root,string node)
        {
            var path=new List<string>();
            using(var next=new Statement(this,"SELECT parent FROM gpo_scope WHERE gpo=?1 AND root=?2 AND node=?3"))
            {for(int i=0;node!=null&&i<130;i++){path.Add(node);next.Bind(1,gpo);next.Bind(2,root);next.Bind(3,node);node=next.Read()?next.Text(0):null;next.Reset();}}
            path.Reverse();return path.ToArray();
        }
        private static string GpoConflictRecord(string record){return GpoConflictRecord(record,"GpoEvidenceConflict");}
        private static string GpoConflictRecord(string record,string field)
        {
            if(record==null)return null;record=record.TrimEnd();
            if(JsonRecordReader.ExtractField(record,field)!=null)return record;
            return record.Substring(0,record.Length-1)+",\""+field+"\":true}";
        }
    }
}






namespace BH.Native
{
    public sealed class OwnershipDescriptor
    {
        public bool Known, OwnerRightsPresent, OwnerRightsWriteDacl, WriteDaclDeny;
        public string OwnerSid, Reason="Missing or unsupported ownership descriptor";
        public static OwnershipDescriptor Analyze(byte[] bytes)
        {
            var result=new OwnershipDescriptor();if(bytes==null)return result;
            try
            {
                var sd=new RawSecurityDescriptor(bytes,0);result.OwnerSid=sd.Owner==null?null:sd.Owner.Value;
                if(sd.DiscretionaryAcl==null||(sd.ControlFlags&ControlFlags.DiscretionaryAclPresent)==0)return result;
                bool unsupported=false;
                foreach(GenericAce ace in sd.DiscretionaryAcl)
                {
                    if((ace.AceFlags&AceFlags.InheritOnly)!=0)continue;
                    var rule=ace as QualifiedAce;
                    if(rule==null){unsupported=true;continue;}
                    bool owner=rule.SecurityIdentifier.Value=="S-1-3-4";
                    if(owner)result.OwnerRightsPresent=true;
                    uint mask=unchecked((uint)rule.AccessMask);if((mask&0x10000000)!=0)mask|=0xf01ff;
                    if(rule.IsCallback){if(owner||(mask&0x40000)!=0)unsupported=true;continue;}
                    if(rule.AceQualifier!=AceQualifier.AccessAllowed&&rule.AceQualifier!=AceQualifier.AccessDenied){unsupported=true;continue;}
                    var objectAce=ace as ObjectAce;
                    if(objectAce!=null&&objectAce.ObjectAceFlags!=ObjectAceFlags.None&&(mask&0x40000)!=0){unsupported=true;continue;}
                    if((mask&0x40000)==0)continue;
                    if(rule.AceQualifier==AceQualifier.AccessDenied)result.WriteDaclDeny=true;
                    if(owner&&rule.AceQualifier==AceQualifier.AccessAllowed)result.OwnerRightsWriteDacl=true;
                }
                result.Known=!unsupported;result.Reason=unsupported?"Unsupported or conditional ACE: ownership control requires review":
                    result.WriteDaclDeny?"Relevant WRITE_DAC deny: full token evaluation required":
                    result.OwnerRightsPresent?"OWNER RIGHTS replaces implicit owner permissions":"No applicable OWNER RIGHTS ACE observed";
            }
            catch(ArgumentException){return result;}
            return result;
        }
        public static string PolicyMode(string value)
        {
            char mode=string.IsNullOrEmpty(value)||value.Length<29?'0':value[28];
            switch(mode){case '0':return "Default";case '1':return "Block";case '2':return "Allow";case '3':return "Restricted";default:return "Block";}
        }
    }
    public sealed partial class GraphIndex
    {
        private readonly JsonRecordWriter ownerSignature=new JsonRecordWriter();
        public string OwnershipScopeStatus="Not evaluated";
        private void InitializeOwnershipInputs()
        {
            Execute(@"DROP TABLE IF EXISTS temp.owner_meta;DROP TABLE IF EXISTS temp.owner_admins;
                CREATE TEMP TABLE owner_meta(id TEXT COLLATE NOCASE PRIMARY KEY,version TEXT,known INTEGER,owner_rights INTEGER,owner_wd INTEGER,
                    deny_wd INTEGER,computer INTEGER,policy TEXT,signature TEXT,conflict INTEGER) WITHOUT ROWID;
                CREATE INDEX owner_conflicts ON owner_meta(id) WHERE conflict<>0;");
        }
        private void RegisterOwnershipNode(string line,string id,string kind,Statement insert,Statement conflict)
        {
            string version=JsonRecordReader.ExtractField(line,"OwnershipMetadataVersion");
            string known=JsonRecordReader.ExtractField(line,"OwnershipAnalysisKnown"),present=JsonRecordReader.ExtractField(line,"OwnerRightsPresent"),wd=JsonRecordReader.ExtractField(line,"OwnerRightsWriteDacl"),deny=JsonRecordReader.ExtractField(line,"OwnershipWriteDaclDeny");
            string computer=JsonRecordReader.ExtractField(line,"OwnershipComputerDerived"),policy=JsonRecordReader.ExtractField(line,"OwnerPolicyMode")??"Unknown";
            if(computer==null)
            {if(kind=="computers")computer="true";else foreach(string cls in JsonRecordReader.StringArray(line,"ObjectClasses"))if(cls.Equals("computer",StringComparison.OrdinalIgnoreCase)||cls.Equals("msDS-ManagedServiceAccount",StringComparison.OrdinalIgnoreCase)||cls.Equals("msDS-GroupManagedServiceAccount",StringComparison.OrdinalIgnoreCase))computer="true";}
            string domainPolicy=JsonRecordReader.ExtractField(line,"OwnerDomainPolicyMode");if(domainPolicy!=null)policy=domainPolicy;
            string signature=ownerSignature.Begin().PropS("Version",version).PropS("Known",known).PropS("Present",present).PropS("Wd",wd).PropS("Deny",deny)
                .PropS("Computer",computer).PropS("Policy",policy).PropS("Owner",JsonRecordReader.ExtractField(line,"OwnerSid"))
                .PropS("SecurityEnabled",JsonRecordReader.ExtractField(line,"SecurityEnabled")).End();
            insert.Bind(1,id);insert.Bind(2,version);insert.Bind(3,known=="true"?"1":"0");insert.Bind(4,present=="true"?"1":"0");insert.Bind(5,wd=="true"?"1":"0");
            insert.Bind(6,deny=="true"?"1":"0");insert.Bind(7,computer=="true"?"1":"0");insert.Bind(8,policy);insert.Bind(9,signature);
            insert.Bind(10,JsonRecordReader.ExtractField(line,"OwnershipEvidenceConflict")!=null?"1":"0");insert.Read();insert.Reset();
            conflict.Bind(1,id);conflict.Bind(2,signature);conflict.Read();conflict.Reset();
        }
        private void DeriveOwnershipControl()
        {
            // Only targets with new metadata are recomputed. Legacy canonical edges
            // stay recorded candidates with an explicit conditional annotation.
            Execute(@"DELETE FROM edges WHERE type IN ('Owns','WriteOwner') AND bucket IN ('acl','access')
                AND target IN (SELECT id FROM owner_meta WHERE version='1' OR conflict<>0);
                CREATE TEMP TABLE owner_admins(domain TEXT COLLATE NOCASE,principal TEXT COLLATE NOCASE,previous TEXT COLLATE NOCASE,depth INTEGER,
                    PRIMARY KEY(domain,principal)) WITHOUT ROWID;
                CREATE INDEX owner_admin_depth ON owner_admins(depth);
                INSERT OR IGNORE INTO owner_admins SELECT substr(n.id,1,length(n.id)-4),n.id,NULL,0 FROM nodes n JOIN owner_meta m ON m.id=n.id
                    WHERE n.kind='groups' AND n.security_enabled='true' AND m.conflict=0 AND (n.id LIKE 'S-1-5-21-%-512' OR n.id LIKE 'S-1-5-21-%-519');
                DROP TABLE IF EXISTS temp.owner_members;
                CREATE TEMP TABLE owner_members(source TEXT COLLATE NOCASE,target TEXT COLLATE NOCASE,PRIMARY KEY(target,source)) WITHOUT ROWID;
                INSERT OR IGNORE INTO owner_members SELECT m.source,m.target FROM edges m JOIN nodes g ON g.id=m.target JOIN nodes s ON s.id=m.source
                    JOIN owner_meta gm ON gm.id=g.id JOIN owner_meta sm ON sm.id=s.id
                    WHERE m.bucket='memberof' AND m.type='MemberOf' AND m.source_dn=0 AND m.target_dn=0 AND g.kind='groups' AND g.security_enabled='true'
                        AND gm.conflict=0 AND sm.conflict=0 AND (s.kind IN ('users','computers') OR (s.kind='groups' AND s.security_enabled='true'));");
            bool adminComplete=true;
            for(int depth=0;Scalar("SELECT count(*) FROM owner_admins WHERE depth="+depth)>0;depth++)
            {
                long count=Scalar("SELECT count(*) FROM owner_admins");
                if(depth>=128||count>=1000000){adminComplete=false;break;}
                Execute(@"INSERT OR IGNORE INTO owner_admins SELECT a.domain,m.source,a.principal,a.depth+1 FROM owner_admins a
                    JOIN owner_members m ON m.target=a.principal WHERE a.depth="+depth+" LIMIT "+(1000000-count));
            }
            long supported=0,conditional=0,suppressed=0;
            var json=new JsonRecordWriter();
            long legacy=0;
            Execute("DROP TABLE IF EXISTS temp.owner_legacy_suppressed;CREATE TEMP TABLE owner_legacy_suppressed(target TEXT COLLATE NOCASE,bucket TEXT,source TEXT COLLATE NOCASE,type TEXT,PRIMARY KEY(target,bucket,source,type)) WITHOUT ROWID;");
            using(var rows=new Statement(this,@"SELECT e.target,e.bucket,e.source,e.type,e.evidence,m.computer FROM edges e JOIN owner_meta m ON m.id=e.target
                WHERE (m.version IS NULL OR m.version<>'1') AND m.conflict=0 AND e.bucket IN ('acl','access') AND e.type IN ('Owns','WriteOwner')"))
            using(var update=new Statement(this,"UPDATE edges SET evidence=?1 WHERE target=?2 AND bucket=?3 AND source=?4 AND type=?5"))
            using(var policyLookup=new Statement(this,"SELECT policy,conflict FROM owner_meta WHERE id=?1"))
            using(var stop=new Statement(this,"INSERT OR IGNORE INTO owner_legacy_suppressed VALUES(?1,?2,?3,?4)"))
            {while(rows.Read()){
                string original=rows.Text(4),mode="Unknown";bool block=false;
                if(rows.Text(5)=="1"&&rows.Text(0).StartsWith("S-1-5-21-",StringComparison.OrdinalIgnoreCase))
                {string id=rows.Text(0);policyLookup.Bind(1,id.Substring(0,id.LastIndexOf('-')));if(policyLookup.Read()){mode=policyLookup.Text(0);block=mode=="Block"||mode=="Restricted"||policyLookup.Text(1)=="1";}policyLookup.Reset();}
                if(block){suppressed++;for(int i=0;i<4;i++)stop.Bind(i+1,rows.Text(i));stop.Read();stop.Reset();}else legacy++;
                if(original!=null&&JsonRecordReader.ExtractField(original,"Derivation")=="OwnershipLegacyV1")
                {if(!block)continue;original=JsonRecordReader.ExtractField(original,"OriginalEvidence");}
                json.Begin().Prop("Source",rows.Text(2)).Prop("Target",rows.Text(0)).Prop("EdgeType",rows.Text(3)).Prop("Derivation","OwnershipLegacyV1")
                    .Prop("Assessment",block?"Suppressed projection":"Conditional legacy candidate").Prop("OwnerPolicyMode",mode)
                    .Prop("Reason",block?"Captured blocking/restricted or conflicting policy and missing target ownership context prevent automatic projection":"This collection lacks the new ownership context; OWNER RIGHTS and server policy were not verified")
                    .Prop("EffectiveAccessVerified",false).PropS("OriginalEvidence",original);
                update.Bind(1,json.End());for(int i=0;i<4;i++)update.Bind(i+2,rows.Text(i));update.Read();update.Reset();
            }}
            Execute(@"INSERT OR REPLACE INTO edges SELECT e.target,'observed',e.source,e.type,e.target_dn,e.source_dn,e.evidence FROM edges e
                JOIN owner_legacy_suppressed s ON s.target=e.target AND s.bucket=e.bucket AND s.source=e.source AND s.type=e.type;
                DELETE FROM edges WHERE (target,bucket,source,type) IN (SELECT target,bucket,source,type FROM owner_legacy_suppressed);");
            using(var raw=new Statement(this,@"SELECT e.target,e.source,e.type,m.known,m.owner_rights,m.owner_wd,m.deny_wd,m.computer,m.policy,m.conflict
                FROM edges e JOIN owner_meta m ON m.id=e.target WHERE e.bucket='observed' AND e.type IN ('OwnsRaw','WriteOwnerRaw') AND m.version='1'
                    AND e.source_dn=0 AND e.target_dn=0 ORDER BY e.target,e.source,e.type"))
            using(var admin=new Statement(this,"SELECT 1 FROM owner_admins WHERE domain=?1 AND principal=?2"))
            using(var domainPolicy=new Statement(this,"SELECT policy,conflict FROM owner_meta WHERE id=?1"))
            using(var write=new Statement(this,"INSERT OR REPLACE INTO edges VALUES(?1,?2,?3,?4,0,0,?5)"))
            {
                while(raw.Read())
                {
                    string target=raw.Text(0),source=raw.Text(1),type=raw.Text(2)=="OwnsRaw"?"Owns":"WriteOwner",policy=raw.Text(8);
                    bool computer=raw.Text(7)=="1",present=raw.Text(4)=="1",explicitWd=raw.Text(5)=="1";
                    string[] adminWitness=new string[0];
                    bool policyConflict=false;string policySource="Target snapshot";
                    if(computer&&target.StartsWith("S-1-5-21-",StringComparison.OrdinalIgnoreCase))
                    {
                        int last=target.LastIndexOf('-');domainPolicy.Bind(1,target.Substring(0,last));
                        if(domainPolicy.Read())
                        {string captured=domainPolicy.Text(0);policyConflict=domainPolicy.Text(1)=="1"||(policy!="Unknown"&&captured!="Unknown"&&captured!=policy);if(policy=="Unknown"){policy=captured;policySource="Captured target-domain policy";}}domainPolicy.Reset();
                    }
                    string assessment="Supported candidate",reason="Implicit owner WRITE_DAC is modeled for this non-computer object";bool usable=true;
                    if(raw.Text(9)=="1"){usable=false;reason="Conflicting ownership metadata across input snapshots";}
                    else if(computer&&policyConflict&&!explicitWd){usable=false;reason="Conflicting captured domain ownership policy";}
                    else if(raw.Text(3)!="1"){usable=false;reason="Ownership descriptor context is incomplete or unsupported";}
                    else if(raw.Text(6)=="1"){usable=false;reason="Relevant WRITE_DAC deny requires full effective-token review";}
                    else if(present&&!explicitWd){usable=false;reason="OWNER RIGHTS is present without a supported explicit WRITE_DAC grant";}
                    else if(explicitWd){reason="Applicable OWNER RIGHTS explicitly grants WRITE_DAC to the owner role";}
                    else if(computer&&policy=="Block")
                    {
                        bool exception=false;int dash=target.LastIndexOf('-');
                        if(adminComplete&&type=="Owns"&&target.StartsWith("S-1-5-21-",StringComparison.OrdinalIgnoreCase)&&dash>0)
                        {admin.Bind(1,target.Substring(0,dash));admin.Bind(2,source);exception=admin.Read();admin.Reset();}
                        usable=exception;reason=exception?"Captured blocking mode; same-domain DA/EA membership supplies an owner exception":"Captured blocking mode; no supported owner exception established";
                        if(exception)adminWitness=OwnershipAdminPath(target.Substring(0,dash),source);
                    }
                    else if(computer&&policy=="Restricted"){usable=false;reason="Newer restricted mode needs operation-specific server evaluation";}
                    else if(computer&&policy!="Allow"){assessment="Conditional candidate";reason="Computer owner behavior depends on server/version defaults; captured mode: "+policy;}
                    else if(computer){reason="Explicit non-blocking policy value captured; server enforcement still unverified";}
                    if(!usable){assessment="Suppressed projection";suppressed++;}else if(assessment=="Conditional candidate")conditional++;else supported++;
                    json.Begin().Prop("Source",source).Prop("Target",target).Prop("EdgeType",type).Prop("Derivation","OwnershipControlV1")
                        .Prop("Assessment",assessment).Prop("Reason",reason).Prop("OwnerRightsPresent",present).Prop("OwnerRightsWriteDacl",explicitWd)
                        .Prop("ComputerDerived",computer).Prop("OwnerPolicyMode",policy).Prop("EffectiveAccessVerified",false).Prop("ServerEnforcementVerified",false);
                    json.Prop("PolicySource",policySource);
                    json.PropArray("AdminMembership",adminWitness);
                    write.Bind(1,target);write.Bind(2,usable?"acl":"observed");write.Bind(3,source);write.Bind(4,type);write.Bind(5,json.End());write.Read();write.Reset();
                }
            }
            // Keep a machine-readable conflict marker in retained nodes and merges.
            using(var rows=new Statement(this,"SELECT n.id,n.record FROM owner_meta m JOIN nodes n ON n.id=m.id WHERE m.conflict<>0 AND n.record IS NOT NULL"))
            using(var update=new Statement(this,"UPDATE nodes SET record=?1 WHERE id=?2"))
            {while(rows.Read()){update.BindRecord(1,GpoConflictRecord(rows.Record(1),"OwnershipEvidenceConflict"));update.Bind(2,rows.Text(0));update.Read();update.Reset();}}
            OwnershipScopeStatus="Ownership relationships: "+supported+" supported projections, "+conditional+" conditional projections, "+suppressed+" suppressed projections; "+legacy+" conditional legacy relationships; effective access remains unverified"+(adminComplete?"":"; admin exception closure incomplete");
            using(var state=new Statement(this,"INSERT OR REPLACE INTO derivation_meta VALUES('ownership',?1)")){state.Bind(1,OwnershipScopeStatus);state.Read();}
        }
        public string OwnershipScopeNote()
        {
            if(Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='derivation_meta'")==0)return "Legacy index: ownership context is unverified";
            using(var s=new Statement(this,"SELECT value FROM derivation_meta WHERE key='ownership'")){return s.Read()?s.Text(0):"Legacy ownership context is unverified";}
        }
        private string[] OwnershipAdminPath(string domain,string principal)
        {
            var path=new List<string>();using(var next=new Statement(this,"SELECT previous FROM owner_admins WHERE domain=?1 AND principal=?2"))
            {for(int i=0;principal!=null&&i<130;i++){path.Add(principal);next.Bind(1,domain);next.Bind(2,principal);principal=next.Read()?next.Text(0):null;next.Reset();}}
            return path.ToArray();
        }
    }
}





namespace BH.Native
{
    public sealed partial class GraphIndex
    {
        private readonly HashSet<string> enrichedGroupIds=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private long adcsSeedAttempts;
        private bool adcsSeedLimited;
        private static string AF(string record,string name){return record==null?null:JsonRecordReader.ExtractField(record,name);}
        private static string[] AA(string record,string name){return record==null?new string[0]:new List<string>(JsonRecordReader.StringArray(record,name)).ToArray();}
        private static string Thumb(string value)
        {
            if(value==null||value.Length!=40)return null;
            foreach(char c in value)if(!Uri.IsHexDigit(c))return null;
            return value.ToUpperInvariant();
        }
        private void InitializeAdcsInputs()
        {
            enrichedGroupIds.Clear();
            Execute(@"DROP TABLE IF EXISTS temp.adcs_meta;
                CREATE TEMP TABLE adcs_meta(id TEXT COLLATE NOCASE PRIMARY KEY,kind TEXT,record BLOB,signature TEXT,conflict INTEGER) WITHOUT ROWID;
                CREATE INDEX adcs_kind ON adcs_meta(kind);");
        }
        private void RegisterAdcsNode(string record,string id,string kind,Statement insert,Statement conflict)
        {
            if(kind!="certtemplates"&&kind!="enterprisecas"&&kind!="rootcas"&&kind!="ntauthstores"&&kind!="computers"&&kind!="users"&&kind!="groups"&&kind!="domains")return;
            if(kind=="groups"&&AF(record,"GroupTypeSource")=="ReadOnlyLDAP")enrichedGroupIds.Add(id);
            var signature=new JsonRecordWriter().Begin().Prop("Kind",kind);
            foreach(string field in new[]{"AdcsMetadataVersion","AdcsMetadataSource","DomainSid","DomainName","Disabled","SecurityEnabled","CertThumbprint","HostingComputer","CAServicePermissionsCollected","AdcsRequiresManagerApproval","AdcsEnrolleeSuppliesSubject","AdcsAuthenticationEnabled","SchemaVersion","RequiredSignatures","AdcsExplicitDenyCount","AdcsInheritedDenyCount"})signature.Prop(field,AF(record,field));
            foreach(string field in new[]{"CertChain","CertThumbprints","AdcsServiceAces","AdcsDirectoryAces"})signature.PropArray(field,AA(record,field));
            string key=signature.End();
            conflict.Bind(1,id);conflict.Bind(2,key);conflict.Read();conflict.Reset();
            insert.Bind(1,id);insert.Bind(2,kind);insert.BindRecord(3,key);insert.Bind(4,key);insert.Bind(5,AF(record,"AdcsEvidenceConflict")=="true"?"1":"0");insert.Read();insert.Reset();
        }
        private static bool AdcsTemplateEligible(string record)
        {
            long schema,signatures;
            return AF(record,"AdcsMetadataVersion")=="1"&&AF(record,"AdcsMetadataSource")=="SharpHound"&&
                AF(record,"AdcsRequiresManagerApproval")=="false"&&AF(record,"AdcsEnrolleeSuppliesSubject")=="true"&&AF(record,"AdcsAuthenticationEnabled")=="true"&&
                long.TryParse(AF(record,"SchemaVersion"),out schema)&&schema>=1&&schema<=4&&long.TryParse(AF(record,"RequiredSignatures"),out signatures)&&signatures>=0&&(schema==1||signatures==0);
        }
        private static bool AdcsDenyFree(string record)
        {
            foreach(string field in new[]{"AdcsExplicitDenyCount","AdcsInheritedDenyCount"})
            {string value=AF(record,field);long count;if(value!=null&&(!long.TryParse(value,out count)||count!=0))return false;}
            foreach(string ace in AA(record,"AdcsDirectoryAces")){string access=AF(ace,"AccessType");if(access!=null&&access!="AccessAllowed")return false;}
            foreach(string ace in AA(record,"AdcsServiceAces")){string access=AF(ace,"AccessType");if(access!=null&&access!="AccessAllowed")return false;}
            return true;
        }
        private void AddAdcsGrants(string id,string record,bool service,Statement grant)
        {
            if(!AdcsDenyFree(record))return;
            foreach(string ace in AA(record,service?"AdcsServiceAces":"AdcsDirectoryAces"))
            {
                string right=AF(ace,"RightName"),type=AF(ace,"PrincipalType"),source=AF(ace,"PrincipalSID"),access=AF(ace,"AccessType");
                if(type=="LocalGroup"||type=="LocalUser"||source==null||(access!=null&&access!="AccessAllowed"))continue;
                if(service?right!="Enroll":right!="Enroll"&&right!="GenericAll"&&right!="AllExtendedRights")continue;
                if(type!="User"&&type!="Computer"&&type!="Group")continue;
                if(adcsSeedAttempts++>=250000){adcsSeedLimited=true;return;}
                grant.Bind(1,id);grant.Bind(2,service?"2":"1");grant.Bind(3,source);grant.Bind(4,source);grant.Bind(5,right);grant.Read();grant.Reset();
            }
        }
        private void DeriveAdcsEsc1()
        {
            adcsSeedAttempts=0;adcsSeedLimited=false;
            InitializeAdcsDiagnostics();
            Execute(@"DELETE FROM edges WHERE type COLLATE NOCASE='ADCSESC1';
                DROP TABLE IF EXISTS temp.adcs_reach;DROP TABLE IF EXISTS temp.adcs_pairs;DROP TABLE IF EXISTS temp.adcs_members;
                CREATE TEMP TABLE adcs_reach(object TEXT COLLATE NOCASE,permission INTEGER,principal TEXT COLLATE NOCASE,next_id TEXT,grant_source TEXT,right_name TEXT,depth INTEGER,
                    PRIMARY KEY(object,permission,principal)) WITHOUT ROWID;
                CREATE INDEX adcs_reach_depth ON adcs_reach(depth);
                CREATE TEMP TABLE adcs_pairs(ca TEXT COLLATE NOCASE,template TEXT COLLATE NOCASE,domain TEXT COLLATE NOCASE,root TEXT,ntauth TEXT,host TEXT,thumb TEXT,
                    PRIMARY KEY(ca,template,domain)) WITHOUT ROWID;
                CREATE TEMP TABLE adcs_members(source TEXT COLLATE NOCASE,target TEXT COLLATE NOCASE,PRIMARY KEY(source,target)) WITHOUT ROWID;
                CREATE INDEX adcs_member_target ON adcs_members(target,source);
                INSERT OR IGNORE INTO adcs_members SELECT e.source,e.target FROM edges e
                    JOIN adcs_meta g ON g.id=e.target AND g.kind='groups' AND g.conflict=0
                    JOIN nodes n ON n.id=g.id AND n.security_enabled='true'
                    JOIN adcs_meta p ON p.id=e.source AND p.kind IN ('users','computers','groups') AND p.conflict=0
                    WHERE e.bucket='memberof' AND e.type='MemberOf' AND e.source_dn=0 AND e.target_dn=0 AND e.source<>e.target;");
            long caCount=0,pairCount=0;
            using(var ca=new Statement(this,"SELECT id,record FROM adcs_meta WHERE kind='enterprisecas' AND conflict=0 ORDER BY id"))
            using(var host=new Statement(this,"SELECT record FROM adcs_meta WHERE id=?1 AND kind='computers' AND conflict=0"))
            using(var roots=new Statement(this,"SELECT id,record FROM adcs_meta WHERE kind='rootcas' AND conflict=0 ORDER BY id"))
            using(var stores=new Statement(this,"SELECT a.id,a.record FROM adcs_meta a JOIN nodes d ON d.id=?1 AND d.kind='domains' WHERE a.kind='ntauthstores' AND a.conflict=0 ORDER BY a.id"))
            using(var templates=new Statement(this,@"SELECT a.id,a.record FROM edges e JOIN adcs_meta a ON a.id=e.source AND a.kind='certtemplates' AND a.conflict=0
                WHERE e.target=?1 AND e.type='PublishedTo' AND e.bucket='observed' AND e.source_dn=0 AND e.target_dn=0 ORDER BY a.id"))
            using(var pair=new Statement(this,"INSERT OR IGNORE INTO adcs_pairs VALUES(?1,?2,?3,?4,?5,?6,?7)"))
            using(var grant=new Statement(this,"INSERT OR IGNORE INTO adcs_reach VALUES(?1,?2,?3,NULL,?4,?5,0)"))
            {
                while(ca.Read())
                {
                    caCount++;string caId=ca.Text(0),record=ca.Record(1),domain=AF(record,"DomainSid"),hosting=AF(record,"HostingComputer"),thumb=Thumb(AF(record,"CertThumbprint"));
                    string[] chain=AA(record,"CertChain");
                    var caProblems=AdcsCaProblems(record);if(caProblems.Count>0){foreach(var problem in caProblems)AdcsStop(caId,"",problem[0],problem[1]);continue;}
                    host.Bind(1,hosting);bool eligible=false;
                    if(host.Read()){string h=host.Record(0);eligible=AF(h,"Disabled")=="false"&&string.Equals(AF(h,"DomainSid"),domain,StringComparison.OrdinalIgnoreCase);}
                    host.Reset();if(!eligible){AdcsStop(caId,hosting??"","CAHostNotQualified","The exact CA host is missing, disabled, has unknown enabled state, or does not match the captured CA domain.");continue;}
                    bool rootMatched=false,ntauthMatched=false,published=false,templateEligible=false;
                    AddAdcsGrants(caId,record,true,grant);
                    while(roots.Read())
                    {
                        string rootRecord=roots.Record(1),targetDomain=AF(rootRecord,"DomainSid");string[] rootChain=AA(rootRecord,"CertChain");
                        if(AF(rootRecord,"AdcsMetadataVersion")!="1"||AF(rootRecord,"AdcsMetadataSource")!="SharpHound"||Thumb(AF(rootRecord,"CertThumbprint"))!=thumb||rootChain.Length!=1||Thumb(rootChain[0])!=thumb||targetDomain==null)continue;
                        rootMatched=true;stores.Bind(1,targetDomain);
                        while(stores.Read())
                        {
                            string storeRecord=stores.Record(1);if(AF(storeRecord,"AdcsMetadataVersion")!="1"||AF(storeRecord,"AdcsMetadataSource")!="SharpHound"||!string.Equals(AF(storeRecord,"DomainSid"),targetDomain,StringComparison.OrdinalIgnoreCase))continue;
                            bool trusted=false;foreach(string trustedThumb in AA(storeRecord,"CertThumbprints"))if(Thumb(trustedThumb)==thumb)trusted=true;
                            if(!trusted)continue;ntauthMatched=true;
                            templates.Bind(1,caId);
                            while(templates.Read())
                            {
                                string template=templates.Text(0),templateRecord=templates.Record(1);published=true;var templateProblems=AdcsTemplateProblems(templateRecord);if(templateProblems.Count>0){foreach(var problem in templateProblems)AdcsStop(template,caId,problem[0],problem[1]);continue;}templateEligible=true;
                                AddAdcsGrants(template,templateRecord,false,grant);
                                pair.Bind(1,caId);pair.Bind(2,template);pair.Bind(3,targetDomain);pair.Bind(4,roots.Text(0));pair.Bind(5,stores.Text(0));pair.Bind(6,hosting);pair.Bind(7,thumb);pair.Read();pair.Reset();
                            }
                            templates.Reset();
                        }
                        stores.Reset();
                    }
                    roots.Reset();
                    if(!rootMatched)AdcsStop(caId,"","RootTrustNotEstablished","No matching supported direct-root certificate record with a target-domain association was supplied.");
                    else if(!ntauthMatched)AdcsStop(caId,"","NTAuthTrustNotEstablished","No matching CA thumbprint in an NTAuth store associated with the same collected target domain was established.");
                    else if(!published)AdcsStop(caId,"","PublicationNotResolved","No published, resolved certificate-template record was supplied for this CA.");
                    else if(!templateEligible)AdcsStop(caId,"","NoEligibleTemplate","Published templates failed or lack supported ESC1 template prerequisites; inspect their individual reasons.");
                }
            }
            pairCount=Scalar("SELECT count(*) FROM adcs_pairs");
            // Well-known authenticated principals apply implicitly to known enabled
            // accounts in the publishing CA's domain. Do not infer anonymous or
            // cross-forest authentication, and never treat a distribution group as a token.
            using(var special=new Statement(this,@"SELECT r.object,r.permission,r.principal,r.grant_source,r.right_name,c.record FROM adcs_reach r
                JOIN adcs_meta c ON c.id=r.object WHERE r.depth=0"))
            using(var accounts=new Statement(this,"SELECT id,record FROM adcs_meta WHERE kind IN ('users','computers') AND conflict=0"))
            using(var insert=new Statement(this,"INSERT OR IGNORE INTO adcs_reach VALUES(?1,?2,?3,NULL,?4,?5,0)"))
            {
                var specials=new List<string[]>();while(special.Read())specials.Add(new[]{special.Text(0),special.Text(1),special.Text(2),special.Text(3),special.Text(4),AF(special.Record(5),"DomainSid"),AF(special.Record(5),"DomainName")});
                foreach(var s in specials)
                {
                    if(adcsSeedLimited)break;
                    string domain=s[5];if(domain==null)continue;
                    if(s[2]!="S-1-1-0"&&s[2]!="S-1-5-11"&&s[2]!=domain+"-S-1-1-0"&&s[2]!=domain+"-S-1-5-11"&&!string.Equals(s[2],s[6]+"-S-1-1-0",StringComparison.OrdinalIgnoreCase)&&!string.Equals(s[2],s[6]+"-S-1-5-11",StringComparison.OrdinalIgnoreCase))continue;
                    while(accounts.Read())
                    {
                        string a=accounts.Record(1);if(AF(a,"Disabled")!="false"||!string.Equals(AF(a,"DomainSid"),domain,StringComparison.OrdinalIgnoreCase))continue;
                        if(adcsSeedAttempts++>=250000){adcsSeedLimited=true;break;}
                        insert.Bind(1,s[0]);insert.Bind(2,s[1]);insert.Bind(3,accounts.Text(0));insert.Bind(4,s[3]);insert.Bind(5,s[4]);insert.Read();insert.Reset();
                    }
                    accounts.Reset();
                }
            }
            bool limited=adcsSeedLimited;
            for(long depth=0;!limited&&Scalar("SELECT count(*) FROM adcs_reach WHERE depth="+depth)>0;depth++)
            {
                long remaining=250000-Scalar("SELECT count(*) FROM adcs_reach");
                if(remaining<=0||depth>=1000){limited=true;break;}
                long newPrincipals=Scalar(@"SELECT count(*) FROM (SELECT DISTINCT r.object,r.permission,m.source FROM adcs_reach r
                    JOIN adcs_members m ON m.target=r.principal WHERE r.depth="+depth+@" AND NOT EXISTS(SELECT 1 FROM adcs_reach x
                    WHERE x.object=r.object AND x.permission=r.permission AND x.principal=m.source) LIMIT "+(remaining+1)+")");
                if(newPrincipals>remaining){limited=true;break;}
                Execute(@"INSERT OR IGNORE INTO adcs_reach SELECT r.object,r.permission,m.source,r.principal,r.grant_source,r.right_name,r.depth+1
                    FROM adcs_reach r JOIN adcs_members m ON m.target=r.principal WHERE r.depth="+depth+@" AND NOT EXISTS(SELECT 1 FROM adcs_reach x WHERE x.object=r.object AND x.permission=r.permission AND x.principal=m.source) ORDER BY r.object,r.permission,m.source;");
            }

            if(!limited)
            using(var candidates=new Statement(this,@"SELECT p.domain,t.principal,p.template,p.ca,p.root,p.ntauth,p.host,p.thumb,t.grant_source,c.grant_source,t.right_name,c.right_name
                FROM adcs_pairs p JOIN adcs_reach t ON t.object=p.template AND t.permission=1
                JOIN adcs_reach c ON c.object=p.ca AND c.permission=2 AND c.principal=t.principal
                JOIN adcs_meta m ON m.id=t.principal AND m.conflict=0
                JOIN nodes n ON n.id=m.id AND n.kind IN ('users','computers','groups') AND (n.kind<>'groups' OR n.security_enabled='true')
                ORDER BY p.domain,t.principal,p.ca,p.template"))
            using(var write=new Statement(this,"INSERT OR IGNORE INTO edges VALUES(?1,'access',?2,'ADCSESC1',0,0,?3)"))
            {
                var evidence=new JsonRecordWriter();
                while(candidates.Read())
                {
                    string domain=candidates.Text(0),principal=candidates.Text(1),template=candidates.Text(2),ca=candidates.Text(3);
                    evidence.Begin().Prop("Source",principal).Prop("Target",domain).Prop("EdgeType","ADCSESC1").Prop("Derivation","AdcsEsc1DirectRootV1")
                        .Prop("Assessment",enrichedGroupIds.Count>0?"Conditional candidate":"Supported candidate").Prop("PostExportGroupClassification",enrichedGroupIds.Count>0).Prop("EffectiveAccessVerified",false).Prop("CertificateIssuanceVerified",false)
                        .Prop("Template",template).Prop("EnterpriseCA",ca).Prop("RootCA",candidates.Text(4)).Prop("NTAuthStore",candidates.Text(5)).Prop("HostingComputer",candidates.Text(6)).Prop("CertThumbprint",candidates.Text(7))
                        .Prop("TemplateGrant",candidates.Text(8)).Prop("CAServiceGrant",candidates.Text(9)).Prop("TemplateRight",candidates.Text(10)).Prop("CAServiceRight",candidates.Text(11))
                        .PropArray("TemplateMembership",AdcsWitness(template,1,principal)).PropArray("CAServiceMembership",AdcsWitness(ca,2,principal))
                        .Prop("EvidenceNote","Imported SharpHound summary; same principal, publishing CA, direct-root thumbprint trust and enabled same-domain host. Full-token effective access, issuance and current authentication enforcement require validation. Membership witnesses show at most 64 objects."+(enrichedGroupIds.Count>0?" Post-export read-only LDAP group classification exists in this dataset; exported permissions and memberships were not revalidated.":""));
                    write.Bind(1,domain);write.Bind(2,principal);write.Bind(3,evidence.End());write.Read();write.Reset();
                }
            }
            using(var rows=new Statement(this,"SELECT n.id,n.record FROM adcs_meta m JOIN nodes n ON n.id=m.id WHERE m.conflict<>0 AND n.record IS NOT NULL"))
            using(var update=new Statement(this,"UPDATE nodes SET record=?1 WHERE id=?2"))
            {while(rows.Read()){update.BindRecord(1,GpoConflictRecord(rows.Record(1),"AdcsEvidenceConflict"));update.Bind(2,rows.Text(0));update.Read();update.Reset();}}
            string note="ESC1 imported direct-root scope: "+caCount+" non-conflicting CAs, "+pairCount+" eligible CA/template/domain combinations; "+Scalar("SELECT count(*) FROM edges WHERE type='ADCSESC1'")+" projected relationships. Intermediate chains, cross-domain CA hosts, LDAP-only enrollment evidence and unsupported metadata suppress inference. Effective access and certificate issuance are unverified."+(limited?" Enrollment seed or membership closure limit reached; all ESC1 projections suppressed.":"");
            StoreAdcsEnrollmentDiagnostics(limited);
            string classification=GroupTypeClassificationText();
            using(var entry=new Statement(this,"INSERT OR REPLACE INTO derivation_meta VALUES('group_classification',?1)")){entry.Bind(1,classification);entry.Read();}
            note+=" "+classification;
            long unknownGroups=Scalar("SELECT count(*) FROM nodes WHERE kind='groups' AND security_enabled IS NULL");
            if(unknownGroups>0)note+=" "+unknownGroups+" collected groups have unknown security-enabled state and cannot extend enrollment membership witnesses.";
            using(var state=new Statement(this,"INSERT OR REPLACE INTO derivation_meta VALUES('adcs',?1)")){state.Bind(1,note);state.Read();}
        }
        private string[] AdcsWitness(string target,int permission,string principal)
        {
            var result=new List<string>();var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            using(var next=new Statement(this,"SELECT next_id,grant_source FROM adcs_reach WHERE object=?1 AND permission=?2 AND principal=?3"))
            {
                while(principal!=null&&result.Count<64&&visited.Add(principal))
                {
                    result.Add(principal);next.Bind(1,target);next.Bind(2,permission.ToString(CultureInfo.InvariantCulture));next.Bind(3,principal);
                    string id=null,grant=null;if(next.Read()){id=next.Text(0);grant=next.Text(1);}next.Reset();
                    if(id==null){if(grant!=null&&!visited.Contains(grant)&&result.Count<64)result.Add(grant);break;}principal=id;
                }
            }
            return result.ToArray();
        }
        public string AdcsScopeNote()
        {
            if(Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='derivation_meta'")==0)return "Legacy index: AD CS prerequisites were not evaluated";
            using(var state=new Statement(this,"SELECT value FROM derivation_meta WHERE key='adcs'")){return state.Read()?state.Text(0):"Legacy index: AD CS prerequisites were not evaluated";}
        }
    }
}




namespace BH.Native
{
    public sealed partial class GraphIndex
    {
        private void InitializeAdcsDiagnostics()
        {
            Execute(@"CREATE TABLE IF NOT EXISTS adcs_diagnostics(object TEXT COLLATE NOCASE,related TEXT COLLATE NOCASE,code TEXT,reason TEXT,
                PRIMARY KEY(object,related,code)) WITHOUT ROWID;DELETE FROM adcs_diagnostics;");
        }
        private void AdcsStop(string id,string related,string code,string reason)
        {
            using(var write=new Statement(this,"INSERT OR IGNORE INTO adcs_diagnostics VALUES(?1,?2,?3,?4)"))
            {write.Bind(1,id);write.Bind(2,related??"");write.Bind(3,code);write.Bind(4,reason);write.Read();}
        }
        private static List<string[]> AdcsCaProblems(string record)
        {
            var result=new List<string[]>();
            if(AF(record,"AdcsMetadataVersion")!="1"||AF(record,"AdcsMetadataSource")!="SharpHound")result.Add(new[]{"UnsupportedCAEvidence","Supported imported CA metadata was not collected; directory inventory alone cannot establish CA-service prerequisites."});
            if(AF(record,"CAServicePermissionsCollected")!="true")result.Add(new[]{"CAServicePermissionsMissing","A successful CA-service permission collection is missing. Directory-object ACLs cannot substitute for service Enroll evidence."});
            if(!AdcsDenyFree(record))result.Add(new[]{"CADenyContext","Reported deny or unsupported ACE context requires full effective-token review."});
            string thumb=Thumb(AF(record,"CertThumbprint"));string[] chain=AA(record,"CertChain");
            if(thumb==null)result.Add(new[]{"CACertificateIdentityMissing","The CA certificate thumbprint is missing or malformed."});
            if(chain.Length!=1||thumb==null||Thumb(chain[0])!=thumb)result.Add(new[]{"UnsupportedCAChain","A matching single-entry direct-root chain was not established. Intermediate chains and missing chain metadata remain unsupported."});
            if(string.IsNullOrEmpty(AF(record,"DomainSid")))result.Add(new[]{"CADomainMissing","The publishing CA domain SID was not captured."});
            if(string.IsNullOrEmpty(AF(record,"HostingComputer")))result.Add(new[]{"CAHostMissing","The exact CA HostingComputer identity was not captured."});
            return result;
        }
        private static List<string[]> AdcsTemplateProblems(string record)
        {
            var result=new List<string[]>();
            if(AF(record,"AdcsMetadataVersion")!="1"||AF(record,"AdcsMetadataSource")!="SharpHound")result.Add(new[]{"UnsupportedTemplateEvidence","Explicit supported imported template metadata is missing."});
            if(AF(record,"AdcsRequiresManagerApproval")!="false")result.Add(new[]{"TemplateApproval","Manager approval is required or its state is unknown."});
            if(AF(record,"AdcsEnrolleeSuppliesSubject")!="true")result.Add(new[]{"TemplateSubject","Requester-supplied subject naming is not enabled or is unknown."});
            if(AF(record,"AdcsAuthenticationEnabled")!="true")result.Add(new[]{"TemplateAuthentication","Authentication purpose is not enabled or is unknown."});
            long schema,signatures;bool validSchema=long.TryParse(AF(record,"SchemaVersion"),out schema)&&schema>=1&&schema<=4;
            if(!validSchema)result.Add(new[]{"TemplateSchema","A supported schema version 1–4 was not established."});
            if(!long.TryParse(AF(record,"RequiredSignatures"),out signatures)||signatures<0||(validSchema&&schema>1&&signatures>0))result.Add(new[]{"TemplateSignatures","The signature requirement is unknown, malformed, or requires signatures for a schema above 1."});
            if(!AdcsDenyFree(record))result.Add(new[]{"TemplateDenyContext","Reported deny or unsupported ACE context requires effective-token review."});
            return result;
        }
        private void StoreAdcsEnrollmentDiagnostics(bool limited)
        {
            using(var pairs=new Statement(this,@"SELECT p.ca,p.template,
                EXISTS(SELECT 1 FROM adcs_reach WHERE object=p.template AND permission=1),
                EXISTS(SELECT 1 FROM adcs_reach WHERE object=p.ca AND permission=2),
                EXISTS(SELECT 1 FROM adcs_reach a JOIN adcs_reach b ON b.principal=a.principal AND b.object=p.ca AND b.permission=2
                    JOIN adcs_meta m ON m.id=a.principal AND m.conflict=0 JOIN nodes n ON n.id=m.id AND n.kind IN ('users','computers','groups')
                        AND (n.kind<>'groups' OR n.security_enabled='true') WHERE a.object=p.template AND a.permission=1)
                FROM adcs_pairs p ORDER BY p.ca,p.template"))
            {
                while(pairs.Read())
                {
                    if(limited)AdcsStop(pairs.Text(0),pairs.Text(1),"MembershipWorkLimit","Enrollment seed or membership work reached its limit; all ESC1 projections were suppressed.");
                    else if(pairs.Text(2)!="1")AdcsStop(pairs.Text(0),pairs.Text(1),"TemplateEnrollmentNotEstablished","No supported template enrollment grant was established for this CA/template combination.");
                    else if(pairs.Text(3)!="1")AdcsStop(pairs.Text(0),pairs.Text(1),"CAServiceEnrollmentNotEstablished","No supported CA-service Enroll grant was established for this combination.");
                    else if(pairs.Text(4)!="1")AdcsStop(pairs.Text(0),pairs.Text(1),"TokenIntersectionNotEstablished","No common known principal was established across the template and CA-service enrollment branches. Unknown group types or missing memberships can prevent expansion.");
                }
            }
            using(var groups=new Statement(this,@"SELECT DISTINCT n.id,n.record FROM adcs_reach r JOIN nodes n ON n.id=r.principal
                WHERE n.kind='groups' AND n.security_enabled IS NULL ORDER BY n.id"))
            {while(groups.Read()){string status=AF(groups.Record(1),"GroupTypeEnrichmentStatus");AdcsStop(groups.Text(0),"","GroupClassificationUnknown","Security-enabled group state is unknown; this group cannot extend derived enrollment membership witnesses."+(status==null?"":" Enrichment status: "+status+"."));}}
            using(var conflicts=new Statement(this,"SELECT id FROM adcs_meta WHERE conflict<>0 ORDER BY id"))
            {while(conflicts.Read())AdcsStop(conflicts.Text(0),"","ConflictingEvidence","Conflicting prerequisite snapshots prevent this object from participating in supported ESC1 inference.");}
        }
        private string GroupTypeClassificationText()
        {
            return enrichedGroupIds.Count==0?"No post-export LDAP group classification was used.":
                enrichedGroupIds.Count+" group identities contain post-export read-only LDAP classification. Exported grants and memberships were not revalidated; ESC1 projections are conditional mixed-time candidates.";
        }
        public string GroupTypeScopeNote()
        {
            if(Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='derivation_meta'")==0)return "Group classification provenance is unavailable in this legacy index.";
            using(var rows=new Statement(this,"SELECT value FROM derivation_meta WHERE key='group_classification'")){return rows.Read()?rows.Text(0):"Group classification provenance is unavailable in this legacy index.";}
        }
        public long AdcsPrerequisiteCount()
        {return Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='adcs_diagnostics'")==0?0:Scalar("SELECT count(*) FROM adcs_diagnostics");}
        // Rows describe unestablished candidate prerequisites, not an exhaustive
        // proof of why an arbitrary source/target query has no possible route.
        public List<string[]> AdcsPrerequisiteRows(int limit,string objectId)
        {
            if(limit<1||limit>5000)throw new ArgumentOutOfRangeException("limit");
            var result=new List<string[]>();if(AdcsPrerequisiteCount()==0)return result;
            using(var rows=new Statement(this,@"SELECT d.object,d.related,d.code,d.reason,COALESCE(a.name,d.object),COALESCE(b.name,d.related)
                FROM adcs_diagnostics d LEFT JOIN nodes a ON a.id=d.object LEFT JOIN nodes b ON b.id=d.related
                WHERE ?1='' OR d.object=?1 COLLATE NOCASE OR d.related=?1 COLLATE NOCASE
                ORDER BY CASE WHEN d.code='GroupClassificationUnknown' THEN 1 ELSE 0 END,d.object,d.related,d.code LIMIT "+limit))
            {rows.Bind(1,objectId??"");while(rows.Read())result.Add(new[]{rows.Text(0),rows.Text(1),rows.Text(2),rows.Text(3),rows.Text(4),rows.Text(5)});}
            return result;
        }
        private void AppendGroupClassificationGap(List<string[]> rows,string id,string record)
        {
            foreach(var row in rows)if(row[2]=="GroupClassificationUnknown")return;
            using(var group=new Statement(this,"SELECT name FROM nodes WHERE id=?1 AND kind='groups' AND security_enabled IS NULL"))
            {
                group.Bind(1,id);if(!group.Read())return;
                string status=record==null?null:AF(record,"GroupTypeEnrichmentStatus");
                rows.Add(new[]{id,"","GroupClassificationUnknown","The security-enabled state is unknown. Derived rules requiring a security-group token cannot expand this membership."+(status==null?"":" Enrichment status: "+status+"."),group.Text(0)??id,""});
            }
        }
    }
}







namespace BH.Native
{
    public sealed class ExposureFinding
    {
        public string Id;
        public string Source;
        public string Target;
        public List<GraphEdge> Steps = new List<GraphEdge>();
        public int Score;
        public string Priority;
        public long DirectMembers;
        public bool MissingObjects;
        public List<string> Reasons = new List<string>();
        public long Sequence;
        public int HopCount;
        public bool PathLimited;
        public string NextPathId;
    }
    public sealed class ExposureAnalysis
    {
        public List<ExposureFinding> Findings = new List<ExposureFinding>();
        public int Visited;
        public bool Truncated;
        public int DepthLimit;
    }
    public sealed class SnapshotComparison
    {
        public long AddedNodes, RemovedNodes, AddedEdges, RemovedEdges, UnchangedEdges;
        public List<GraphEdge> AddedSample = new List<GraphEdge>();
        public List<GraphEdge> RemovedSample = new List<GraphEdge>();
    }
    public sealed partial class GraphIndex
    {
        private static int CapabilityWeight(string type)
        {
            switch(GraphRelationships.CanonicalType(type))
            {
                case "ADCSESC1": case "DCSync": case "GenericAll": case "WriteDacl": return 40;
                case "AddMember": case "AddSelf": case "WriteOwner": case "Owns":
                case "ForceChangePassword": case "AddKeyCredentialLink": return 35;
                case "MemberOf": return 0;
                case "HasSession": return 15;
                default: return 25;
            }
        }
        private static string FindingId(List<GraphEdge> steps)
        {
            // Length prefixes prevent ambiguous identifiers; normalize Windows identity casing.
            var text = new StringBuilder();
            foreach(var e in steps)
                foreach(string token in new[] { e.Source, e.Target, e.EdgeType })
                { string value=token.ToUpperInvariant(); text.Append(value.Length).Append(':').Append(value); }
            using(var hash=SHA256.Create())
                return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-", "").ToLowerInvariant();
        }
        public long DirectMemberCount(string id)
        {
            using(var s=new Statement(this,"SELECT count(*) FROM edges WHERE target=?1 AND bucket='memberof' AND source<>target"))
            { s.Bind(1,id); s.Read(); return long.Parse(s.Text(0)); }
        }
        public List<string[]> DomainTargets() { return Query("SELECT id,name FROM nodes WHERE kind='domains'",2); }
        // One reverse BFS from all privileged targets. Each identity retains one shortest
        // recorded chain. The visit, depth and finding caps bound memory and report size.
        public ExposureAnalysis AnalyzeExposures(string[] targets, int maxVisited, int maxFindings, int maxDepth)
        {
            if(maxVisited<1 || maxFindings<1 || maxDepth<1) throw new ArgumentOutOfRangeException();
            var result=new ExposureAnalysis { DepthLimit=maxDepth };
            var next=new Dictionary<string,GraphEdge>(StringComparer.OrdinalIgnoreCase);
            var depths=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);
            var queue=new Queue<string>();
            var allowed=new HashSet<string>(GraphRelationships.FilterTypes(),StringComparer.OrdinalIgnoreCase);
            foreach(string target in targets)
            {
                if(next.ContainsKey(target)) continue;
                if(next.Count>=maxVisited) { result.Truncated=true; break; }
                next.Add(target,new GraphEdge()); depths.Add(target,0); queue.Enqueue(target);
            }
            using(var incoming=Incoming())
            {
                while(queue.Count>0 && !result.Truncated)
                {
                    string current=queue.Dequeue();
                    incoming.Bind(1,current);
                    while(incoming.Read())
                    {
                        var e=ReadEdge(incoming,current);
                        if(!allowed.Contains(e.EdgeType) || next.ContainsKey(e.Source)) continue;
                        if(depths[current]>=maxDepth || next.Count>=maxVisited) { result.Truncated=true; break; }
                        next.Add(e.Source,e);depths.Add(e.Source,depths[current]+1);queue.Enqueue(e.Source);
                        var path=new List<GraphEdge>(); string id=e.Source; int weight=0; bool missing=false;
                        while(next[id].Source!=null) {var step=next[id];path.Add(step);weight=Math.Max(weight,CapabilityWeight(step.EdgeType));id=step.Target;}
                        // Pure memberships are expected context, not a security finding.
                        if(weight==0)continue;
                        foreach(var step in path)if(Node(step.Source)==null)missing=true;
                        var finding=new ExposureFinding {Source=e.Source,Target=id,Steps=path,MissingObjects=missing};
                        finding.Id=FindingId(path);finding.Score=30+weight;
                        finding.Reasons.Add("Recorded chain reaches a selected review target (+30).");
                        finding.Reasons.Add("Strongest permission or access capability on this chain (+"+weight+").");
                        var source=Node(e.Source);
                        if(source!=null && source[1]=="groups")
                        {
                            finding.DirectMembers=DirectMemberCount(e.Source);
                            int breadth=finding.DirectMembers>=100?15:finding.DirectMembers>0?5:0;
                            finding.Score+=breadth;
                            if(breadth>0)finding.Reasons.Add(finding.DirectMembers+" recorded direct group members (+"+breadth+").");
                        }
                        if(path.Count<=2){finding.Score+=5;finding.Reasons.Add("At most two recorded hops (+5).");}
                        if(missing){finding.Score-=10;finding.Reasons.Add("One or more source objects are outside the supplied object data (-10; validate identity).");}
                        finding.Priority=finding.Score>=65?"High review priority":"Medium review priority";
                        result.Findings.Add(finding);
                        if(result.Findings.Count>=maxFindings){result.Truncated=true;break;}
                    }
                    incoming.Reset();
                }
            }
            result.Visited=next.Count;
            result.Findings.Sort((a,b)=>{int order=b.Score.CompareTo(a.Score);return order!=0?order:StringComparer.Ordinal.Compare(a.Id,b.Id);});
            return result;
        }
        public bool ContainsPath(List<GraphEdge> steps)
        {
            using(var s=new Statement(this,"SELECT 1 FROM edges WHERE target=?1 AND source=?2 AND type COLLATE NOCASE=?3 AND "+TraversalPredicate("")+" LIMIT 1"))
                foreach(var e in steps){s.Bind(1,e.Target);s.Bind(2,e.Source);s.Bind(3,e.EdgeType);bool found=s.Read();s.Reset();if(!found)return false;}
            return steps.Count>0;
        }
        public List<string[]> ObjectRelationships(string id, int limit)
        {
            if(limit<1 || limit>1000)throw new ArgumentOutOfRangeException("limit");
            var rows=new List<string[]>();
            using(var s=new Statement(this,"SELECT source,target,type,bucket,evidence FROM edges WHERE source=?1 OR target=?1 LIMIT "+limit))
            {s.Bind(1,id);while(s.Read())rows.Add(new[]{s.Text(0),s.Text(1),s.Text(2),s.Text(3),s.Text(4)});}
            return rows;
        }
        public SnapshotComparison CompareSnapshot(string baselinePath)
        {
            if(!File.Exists(baselinePath))throw new FileNotFoundException("Baseline graph index was not found.",baselinePath);
            using(var attach=new Statement(this,"ATTACH DATABASE ?1 AS baseline")){attach.Bind(1,Path.GetFullPath(baselinePath));attach.Read();}
            try
            {
                var r=new SnapshotComparison();
                r.AddedNodes=Scalar("SELECT count(*) FROM nodes n WHERE NOT EXISTS(SELECT 1 FROM baseline.nodes b WHERE b.id=n.id)");
                r.RemovedNodes=Scalar("SELECT count(*) FROM baseline.nodes n WHERE NOT EXISTS(SELECT 1 FROM main.nodes b WHERE b.id=n.id)");
                string added=@"FROM main.edges e WHERE NOT EXISTS(SELECT 1 FROM baseline.edges b WHERE
                    b.target=e.target AND b.bucket=e.bucket AND b.source=e.source AND b.type=e.type AND b.source_dn=e.source_dn AND b.target_dn=e.target_dn)";
                string removed=@"FROM baseline.edges e WHERE NOT EXISTS(SELECT 1 FROM main.edges b WHERE
                    b.target=e.target AND b.bucket=e.bucket AND b.source=e.source AND b.type=e.type AND b.source_dn=e.source_dn AND b.target_dn=e.target_dn)";
                r.AddedEdges=Scalar("SELECT count(*) "+added);r.RemovedEdges=Scalar("SELECT count(*) "+removed);
                r.UnchangedEdges=Scalar("SELECT count(*) FROM main.edges")-r.AddedEdges;
                foreach(var row in Query("SELECT source,target,type "+added+" LIMIT 50",3))r.AddedSample.Add(new GraphEdge{Source=row[0],Target=row[1],EdgeType=row[2]});
                foreach(var row in Query("SELECT source,target,type "+removed+" LIMIT 50",3))r.RemovedSample.Add(new GraphEdge{Source=row[0],Target=row[1],EdgeType=row[2]});
                return r;
            }
            finally{Execute("DETACH DATABASE baseline");}
        }
        private long Scalar(string sql){using(var s=new Statement(this,sql)){s.Read();return long.Parse(s.Text(0));}}
    }
}







namespace BH.Native
{
    public sealed class DiskAnalysisProgress
    {
        public long Visited, Processed, Findings, Pending;
        public string Status, StopReason, PathRules, CurrentPathRules;
        public double ElapsedSeconds;
        public int Depth;
    }
    public sealed partial class GraphIndex
    {
        private string DeepValue(string key)
        {
            using(var s=new Statement(this,"SELECT value FROM analysis_meta WHERE key=?1"))
            {s.Bind(1,key);return s.Read()?s.Text(0):null;}
        }
        private void SetDeepValue(string key,string value)
        {
            using(var s=new Statement(this,"INSERT OR REPLACE INTO analysis_meta VALUES(?1,?2)"))
            {s.Bind(1,key);s.Bind(2,value);s.Read();}
        }
        public bool HasDiskAnalysis()
        {
            return Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='analysis_meta'")>0;
        }
        public bool HasCurrentDiskAnalysis()
        {return HasDiskAnalysis() && DeepValue("path_rules")==GraphRelationships.PolicyVersion;}
        public bool DiskTargetsMatch(string[] targets)
        {
            if(!HasCurrentDiskAnalysis())return false;
            var canonical=(string[])targets.Clone();Array.Sort(canonical,StringComparer.OrdinalIgnoreCase);
            return DeepValue("targets")==string.Join("\n",canonical).ToUpperInvariant();
        }
        private void RequireCurrentAnalysis()
        {
            if(HasDiskAnalysis() && !HasCurrentDiskAnalysis())
                throw new InvalidDataException("Saved analysis uses different path rules (saved "+(DeepValue("path_rules")??"unknown")+", current "+GraphRelationships.PolicyVersion+"). Update scanner and viewer together, then regenerate the report in a new output folder if needed; the collected data can be reused.");
        }
        public string DiskSourceFingerprint(){return HasDiskAnalysis()?DeepValue("source"):null;}
        public void PrepareDiskAnalysis(string[] targets,string fingerprint)
        {if(!HasDiskAnalysis())InitializeDiskAnalysis(targets,fingerprint);}
        public DiskAnalysisProgress DiskAnalysisState()
        {
            if(!HasDiskAnalysis())return new DiskAnalysisProgress {Status="NotStarted",StopReason="No saved analysis",CurrentPathRules=GraphRelationships.PolicyVersion};
            bool current=HasCurrentDiskAnalysis();
            return new DiskAnalysisProgress {
                Visited=long.Parse(DeepValue("visited")),Processed=long.Parse(DeepValue("processed")),
                Findings=long.Parse(DeepValue("findings")),Status=current?DeepValue("status"):"Outdated",StopReason=current?DeepValue("reason"):"Saved path rules "+(DeepValue("path_rules")??"unknown")+"; viewer rules "+GraphRelationships.PolicyVersion+". Rebuild this report from its collected data; a new AD scan is not required.",PathRules=DeepValue("path_rules"),CurrentPathRules=GraphRelationships.PolicyVersion,
                Pending=long.Parse(DeepValue("visited"))-long.Parse(DeepValue("processed")),Depth=int.Parse(DeepValue("depth"))
            };
        }
        private void InitializeDiskAnalysis(string[] targets,string fingerprint)
        {
            Execute("BEGIN IMMEDIATE");
            try {
            Execute(@"CREATE TABLE analysis_meta(key TEXT PRIMARY KEY,value TEXT) WITHOUT ROWID;
                CREATE TABLE analysis_nodes(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT COLLATE NOCASE UNIQUE,
                next_id TEXT,edge_type TEXT,root TEXT,depth INTEGER,weight INTEGER,missing INTEGER,
                members INTEGER,score INTEGER,processed INTEGER DEFAULT 0,
                cursor_bucket TEXT DEFAULT '',cursor_source TEXT DEFAULT '',cursor_type TEXT DEFAULT '');
                CREATE INDEX analysis_queue ON analysis_nodes(seq) WHERE processed=0;
                CREATE INDEX analysis_rank ON analysis_nodes(score DESC,seq) WHERE weight>0;");
                using(var insert=new Statement(this,@"INSERT OR IGNORE INTO analysis_nodes
                    (id,root,depth,weight,missing,members,score) VALUES(?1,?1,0,0,0,0,0)"))
                    foreach(string id in targets){insert.Bind(1,id);insert.Read();insert.Reset();}
                SetDeepValue("version","1");SetDeepValue("source",fingerprint);
                SetDeepValue("path_rules",GraphRelationships.PolicyVersion);
                SetDeepValue("queue_format","partial-v1");
                var canonical=(string[])targets.Clone();Array.Sort(canonical,StringComparer.OrdinalIgnoreCase);
                SetDeepValue("targets",string.Join("\n",canonical).ToUpperInvariant());
                SetDeepValue("visited",Scalar("SELECT count(*) FROM analysis_nodes").ToString(CultureInfo.InvariantCulture));
                SetDeepValue("processed","0");SetDeepValue("findings","0");SetDeepValue("depth","0");
                SetDeepValue("status","Ready");SetDeepValue("reason","Ready to analyze");Execute("COMMIT");
            }catch{Execute("ROLLBACK");throw;}
        }
        private void SaveDiskState(DiskAnalysisProgress p)
        {
            SetDeepValue("visited",p.Visited.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("processed",p.Processed.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("findings",p.Findings.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("depth",p.Depth.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("status",p.Status);SetDeepValue("reason",p.StopReason);
        }
        // A fixed-size batch is read before writes. Both the FIFO frontier and predecessor
        // links live in SQLite. Edge cursors are committed with discovered identities, so a
        // stopped or interrupted batch is replayed without skipping or duplicating work.
        public DiskAnalysisProgress AnalyzeDisk(string[] targets,string fingerprint,int depthLimit,long visitLimit,
            int secondsLimit,string cancelFile,Action<DiskAnalysisProgress> progress)
        {
            if(depthLimit<0 || visitLimit<0 || secondsLimit<0)throw new ArgumentOutOfRangeException();
            if(!HasDiskAnalysis())InitializeDiskAnalysis(targets,fingerprint);
            RequireCurrentAnalysis();
            var canonical=(string[])targets.Clone();Array.Sort(canonical,StringComparer.OrdinalIgnoreCase);
            if(DeepValue("version")!="1" || DeepValue("source")!=fingerprint ||
                DeepValue("targets")!=string.Join("\n",canonical).ToUpperInvariant())
                throw new InvalidDataException("Saved analysis belongs to a different snapshot or target set. Use a new output folder.");
            if(DeepValue("queue_format")!="partial-v1")
            {
                Execute("BEGIN IMMEDIATE");
                try{Execute("DROP INDEX analysis_queue; CREATE INDEX analysis_queue ON analysis_nodes(seq) WHERE processed=0;");SetDeepValue("queue_format","partial-v1");Execute("COMMIT");}
                catch{Execute("ROLLBACK");throw;}
            }
            var state=DiskAnalysisState();var clock=Stopwatch.StartNew();double lastUpdate=-2;
            if(state.Status=="Completed")return state;
            state.Status="Running";state.StopReason="Search in progress";
            var allowed=new HashSet<string>(GraphRelationships.FilterTypes(),StringComparer.OrdinalIgnoreCase);
            bool transaction=false;int batches=0;double lastCheckpoint=0;
            using(var frontier=new Statement(this,@"SELECT seq,id,root,depth,weight,missing,cursor_bucket,cursor_source,cursor_type
                FROM analysis_nodes WHERE processed=0 ORDER BY seq LIMIT 1"))
            using(var incoming=new Statement(this,"SELECT source,type,bucket FROM edges WHERE target=?1 AND "+TraversalPredicate("")+@"
                AND (bucket,source,type)>(?2,?3,?4) ORDER BY bucket,source,type LIMIT 256"))
            using(var exists=new Statement(this,"SELECT 1 FROM analysis_nodes WHERE id=?1"))
            using(var insert=new Statement(this,@"INSERT INTO analysis_nodes
                (id,next_id,edge_type,root,depth,weight,missing,members,score) VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9)"))
            using(var cursor=new Statement(this,@"UPDATE analysis_nodes SET cursor_bucket=?2,cursor_source=?3,cursor_type=?4,
                processed=?5 WHERE seq=?1"))
            {
                while(true)
                {
                    state.ElapsedSeconds=clock.Elapsed.TotalSeconds;state.Pending=state.Visited-state.Processed;
                    if(cancelFile!=null && File.Exists(cancelFile)){state.Status="Cancelled";state.StopReason="Cancellation requested; resume is available";break;}
                    if(secondsLimit>0 && clock.Elapsed.TotalSeconds>=secondsLimit){state.Status="TimeLimit";state.StopReason="Time budget reached; resume is available";break;}
                    if(!frontier.Read()){frontier.Reset();state.Status="Completed";state.StopReason="Frontier exhausted for supported relationships and the selected targets";break;}
                    string sequence=frontier.Text(0),id=frontier.Text(1),root=frontier.Text(2);
                    int depth=int.Parse(frontier.Text(3)),weight=int.Parse(frontier.Text(4)),missing=int.Parse(frontier.Text(5));
                    string lastBucket=frontier.Text(6),lastSource=frontier.Text(7),lastType=frontier.Text(8);frontier.Reset();
                    state.Depth=depth;
                    incoming.Bind(1,id);incoming.Bind(2,lastBucket);incoming.Bind(3,lastSource);incoming.Bind(4,lastType);
                    var batch=new List<string[]>();while(incoming.Read())batch.Add(new[]{incoming.Text(0),incoming.Text(1),incoming.Text(2)});incoming.Reset();
                    if(!transaction){Execute("BEGIN IMMEDIATE");transaction=true;}
                    try {
                        bool blocked=false;
                        foreach(var edge in batch)
                        {
                            bool found;
                            exists.Bind(1,edge[0]);found=exists.Read();exists.Reset();
                            if(allowed.Contains(edge[1]) && !found)
                            {
                                if(depthLimit>0 && depth>=depthLimit){state.Status="DepthLimit";state.StopReason="Depth budget reached; raise it or select Deep analysis to resume";blocked=true;break;}
                                if(visitLimit>0 && state.Visited>=visitLimit){state.Status="VisitLimit";state.StopReason="Identity budget reached; raise it to resume";blocked=true;break;}
                                int childWeight=Math.Max(weight,CapabilityWeight(edge[1]));
                                var node=Node(edge[0]);int childMissing=missing!=0 || node==null?1:0;
                                long members=node!=null && node[1]=="groups" && childWeight>0?DirectMemberCount(edge[0]):0;
                                int score=childWeight==0?0:30+childWeight+(depth+1<=2?5:0)+(members>=100?15:members>0?5:0)-(childMissing!=0?10:0);
                                insert.Bind(1,edge[0]);insert.Bind(2,id);insert.Bind(3,edge[1]);insert.Bind(4,root);
                                insert.Bind(5,(depth+1).ToString(CultureInfo.InvariantCulture));insert.Bind(6,childWeight.ToString(CultureInfo.InvariantCulture));
                                insert.Bind(7,childMissing.ToString());insert.Bind(8,members.ToString(CultureInfo.InvariantCulture));insert.Bind(9,score.ToString());
                                insert.Read();insert.Reset();state.Visited++;if(childWeight>0)state.Findings++;
                            }
                            lastBucket=edge[2];lastSource=edge[0];lastType=edge[1];
                        }
                        bool done=!blocked && batch.Count<256;
                        cursor.Bind(1,sequence);cursor.Bind(2,lastBucket);cursor.Bind(3,lastSource);cursor.Bind(4,lastType);cursor.Bind(5,done?"1":"0");cursor.Read();cursor.Reset();
                        if(done)state.Processed++;batches++;
                        if(blocked || batches>=128 || clock.Elapsed.TotalSeconds-lastCheckpoint>=1)
                        {SaveDiskState(state);Execute("COMMIT");transaction=false;batches=0;lastCheckpoint=clock.Elapsed.TotalSeconds;}
                        if(blocked)break;
                    }catch{if(transaction){Execute("ROLLBACK");transaction=false;}throw;}
                    if(progress!=null && clock.Elapsed.TotalSeconds-lastUpdate>=1){lastUpdate=clock.Elapsed.TotalSeconds;state.ElapsedSeconds=clock.Elapsed.TotalSeconds;state.Pending=state.Visited-state.Processed;progress(state);}
                }
            }
            state.Pending=state.Visited-state.Processed;state.ElapsedSeconds=clock.Elapsed.TotalSeconds;
            if(!transaction)Execute("BEGIN IMMEDIATE");try{SaveDiskState(state);Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}
            if(progress!=null)progress(state);return state;
        }
        public List<ExposureFinding> DiskFindingPage(int afterScore,long afterSequence,int limit)
        {
            if(limit<1 || limit>200)throw new ArgumentOutOfRangeException("limit");
            var result=new List<ExposureFinding>();if(!HasDiskAnalysis())return result;
            RequireCurrentAnalysis();
            var entries=new List<string[]>();
            // Two range seeks handle mixed score-descending/sequence-ascending order
            // without rescanning previously viewed candidates through a large OR filter.
            ReadDiskPage(entries,"score=?1 AND seq>?2",afterScore,afterSequence,limit);
            if(entries.Count<limit)ReadDiskPage(entries,"score<?1",afterScore,afterSequence,limit-entries.Count);
            foreach(var row in entries)
            {
                var f=new ExposureFinding {Source=row[0],Target=row[1],HopCount=int.Parse(row[2]),MissingObjects=row[4]=="1",
                    DirectMembers=long.Parse(row[5]),Score=int.Parse(row[6]),Sequence=long.Parse(row[7])};
                f.Priority=f.Score>=65?"High review priority":"Medium review priority";
                f.Reasons.Add("Recorded chain reaches a selected review target (+30).");
                f.Reasons.Add("Strongest permission or access capability on this chain (+"+row[3]+").");
                if(f.DirectMembers>0)f.Reasons.Add(f.DirectMembers+" recorded direct group members (+"+(f.DirectMembers>=100?15:5)+").");
                if(f.HopCount<=2)f.Reasons.Add("At most two recorded hops (+5).");
                if(f.MissingObjects)f.Reasons.Add("One or more source objects are outside the supplied object data (-10; validate identity).");
                string current=f.Source;
                using(var next=new Statement(this,"SELECT next_id,edge_type FROM analysis_nodes WHERE id=?1"))
                    while(f.Steps.Count<256)
                    {next.Bind(1,current);bool found=next.Read();string target=found?next.Text(0):null,type=found?next.Text(1):null;next.Reset();if(target==null)break;f.Steps.Add(new GraphEdge{Source=current,Target=target,EdgeType=type,Evidence=EdgeEvidence(current,target,type)});current=target;}
                f.PathLimited=f.Steps.Count<f.HopCount;f.NextPathId=f.PathLimited?current:null;
                // Stable path IDs are retained for fully embedded chains; long chains use identity+target.
                f.Id=f.PathLimited?FindingId(new List<GraphEdge>{new GraphEdge{Source=f.Source,Target=f.Target,EdgeType="LongRecordedChain"}}):FindingId(f.Steps);
                result.Add(f);
            }
            return result;
        }
        private void ReadDiskPage(List<string[]> rows,string predicate,int score,long sequence,int limit)
        {
            using(var page=new Statement(this,@"SELECT id,root,depth,weight,missing,members,score,seq FROM analysis_nodes
                WHERE weight>0 AND "+predicate+" ORDER BY score DESC,seq LIMIT "+limit))
            {
                page.Bind(1,score.ToString());if(predicate.IndexOf("?2",StringComparison.Ordinal)>=0)page.Bind(2,sequence.ToString());
                while(page.Read()){var row=new string[8];for(int i=0;i<8;i++)row[i]=page.Text(i);rows.Add(row);}
            }
        }
        public List<GraphEdge> DiskPathPage(string start,int limit)
        {
            RequireCurrentAnalysis();
            if(limit<1 || limit>1000)throw new ArgumentOutOfRangeException("limit");
            var rows=new List<GraphEdge>();
            using(var next=new Statement(this,"SELECT next_id,edge_type FROM analysis_nodes WHERE id=?1"))
                while(rows.Count<limit){next.Bind(1,start);bool found=next.Read();string target=found?next.Text(0):null,type=found?next.Text(1):null;next.Reset();if(target==null)break;rows.Add(new GraphEdge{Source=start,Target=target,EdgeType=type,Evidence=EdgeEvidence(start,target,type)});start=target;}
            return rows;
        }
    }
}
















namespace BH.Native
{
    // All viewer connections open SQLITE_OPEN_READONLY. Requests never run supplied SQL.
    public sealed partial class GraphIndex
    {
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
        private delegate int ViewerProgress(IntPtr unused);
        [DllImport(Library, CallingConvention=CallingConvention.Cdecl)]
        private static extern void sqlite3_progress_handler(IntPtr handle,int instructions,ViewerProgress callback,IntPtr unused);
        private ViewerProgress viewerProgress;
        private Stopwatch viewerClock;
        private volatile bool viewerCancelled;
        public void ViewerCancel(){viewerCancelled=true;}
        public void ViewerBudget()
        {
            Execute("PRAGMA query_only=ON; PRAGMA cache_size=-8192;");
            viewerClock=Stopwatch.StartNew();
            viewerProgress=delegate(IntPtr unused){return viewerCancelled||viewerClock.ElapsedMilliseconds>10000?1:0;};
            sqlite3_progress_handler(db,1000,viewerProgress,IntPtr.Zero);
        }
        private void ViewerCheck(){if(viewerCancelled)throw new OperationCanceledException("Query cancelled; results are incomplete.");if(viewerClock.ElapsedMilliseconds>10000)throw new IOException("Query time limit reached. Narrow the query or choose a closer source/target.");}
        private Dictionary<string,object> VNode(string id)
        {var n=Node(id);return ViewerJson.Map("i",id,"n",n==null?id:n[0],"t",n==null?"?":n[1]);}
        private Dictionary<string,object> VEdge(GraphEdge e)
        {var s=VNode(e.Source);var t=VNode(e.Target);return ViewerJson.Map("s",e.Source,"t",e.Target,"ty",e.EdgeType,"sn",s["n"],"tn",t["n"],"st",s["t"],"tt",t["t"],"Evidence",e.Evidence);}
        private List<object> VEdges(List<GraphEdge> edges)
        {var result=new List<object>();foreach(var e in edges){ViewerCheck();result.Add(VEdge(e));}return result;}
        public object ViewerSummary()
        {return ViewerJson.Map("Nodes",NodeCounts(),"Edges",EdgeCounts(),"Analysis",DiskAnalysisState(),"GpoScope",GpoScopeNote(),"OwnershipScope",OwnershipScopeNote(),"AdcsScope",AdcsScopeNote(),"PrerequisiteGaps",AdcsPrerequisiteRows(30,null),"PrerequisiteGapCount",AdcsPrerequisiteCount());}
        // Scan bounded windows in primary-key order: no index creation or unbounded name-sort.
        // The returned cursor is the last INSPECTED row, including nonmatching rows.
        public object ViewerSearch(string query,string after)
        {
            var rows=new List<object>();string cursor=after;int scanned=0;bool more=false;
            using(var s=new Statement(this,"SELECT id,name,kind FROM nodes WHERE id>?1 ORDER BY id LIMIT 50001"))
            {
                s.Bind(1,after);
                while(s.Read())
                {
                    if(scanned==50000||rows.Count==50){more=true;break;}
                    ViewerCheck();cursor=s.Text(0);scanned++;string name=s.Text(1)??cursor;
                    if(query.Length==0||cursor.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)
                        rows.Add(ViewerJson.Map("i",cursor,"n",name,"t",s.Text(2)));
                }
            }
            return ViewerJson.Map("Rows",rows,"After",cursor,"More",more,"Scanned",scanned);
        }
        public object ViewerFindings(int score,long sequence,string query)
        {
            var rows=new List<object>();int scanned=0,lastScore=score;long lastSequence=sequence;bool more=false;
            if(!HasDiskAnalysis())return ViewerJson.Map("Rows",rows,"More",false,"Scanned",0,"AfterScore",score,"AfterSequence",sequence);
            RequireCurrentAnalysis();
            // Two indexed range seeks preserve score DESC / sequence ASC ordering.
            foreach(string predicate in new string[]{"a.score=?1 AND a.seq>?2","a.score<?1"})
            {
                using(var s=new Statement(this,@"SELECT a.id,a.root,a.depth,a.score,a.seq,n.name,t.name FROM analysis_nodes a
                    LEFT JOIN nodes n ON n.id=a.id LEFT JOIN nodes t ON t.id=a.root
                    WHERE a.weight>0 AND "+predicate+" ORDER BY a.score DESC,a.seq LIMIT 10001"))
                {
                    s.Bind(1,score.ToString(CultureInfo.InvariantCulture));if(predicate.IndexOf("?2",StringComparison.Ordinal)>=0)s.Bind(2,sequence.ToString(CultureInfo.InvariantCulture));
                    while(s.Read())
                    {
                        if(scanned==10000||rows.Count==50){more=true;break;}
                        ViewerCheck();scanned++;lastScore=int.Parse(s.Text(3));lastSequence=long.Parse(s.Text(4));
                        string source=s.Text(0),target=s.Text(1),sn=s.Text(5)??source,tn=s.Text(6)??target;
                        if(query.Length==0||(sn+" "+tn+" "+source+" "+target).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)
                            rows.Add(ViewerJson.Map("Source",ViewerJson.Map("i",source,"n",sn),"Target",ViewerJson.Map("i",target,"n",tn),"HopCount",int.Parse(s.Text(2)),"Score",lastScore));
                    }
                }
                if(more)break;
            }
            return ViewerJson.Map("Rows",rows,"More",more,"Scanned",scanned,"AfterScore",lastScore,"AfterSequence",lastSequence);
        }
        public object ViewerRecordedPath(string start)
        {
            if(!HasDiskAnalysis())throw new IOException("This index has no saved deep analysis. Generate a Deep report first, or use Find a path.");
            string root;int depth,score,weight;long members;bool missing;
            using(var s=new Statement(this,"SELECT root,depth,score,weight,missing,members FROM analysis_nodes WHERE id=?1"))
            {s.Bind(1,start);if(!s.Read())throw new IOException("No saved path for this object.");root=s.Text(0);depth=int.Parse(s.Text(1));score=int.Parse(s.Text(2));weight=int.Parse(s.Text(3));missing=s.Text(4)=="1";members=long.Parse(s.Text(5));}
            var reasons=new List<string>();reasons.Add("Recorded chain reaches a selected review target (+30).");reasons.Add("Strongest recorded permission or access capability on this chain (+"+weight+").");
            if(members>0)reasons.Add(members+" recorded direct group members (+"+(members>=100?15:5)+").");if(depth<=2)reasons.Add("At most two recorded hops (+5).");if(missing)reasons.Add("A source identity is outside the supplied object records (-10; validate identity).");
