guide.Add("ForceChangePassword|users",new string[]{"This is reset-password authority on the target account; it differs from ordinary password change by the account owner.","Check the exact extended right, target protections, deny context, whether this is a service account and whether the grant is intended.","Limit reset-password delegation to the approved helpdesk role and intended account scope.","Rescan the delegation and test the legitimate support process without resetting production/service credentials merely for validation.","Resetting a service identity can interrupt applications; some protected data and dependent credentials may be affected."});
guide.Add("ReadLAPSPassword|computers",new string[]{"This is a managed local-account secret-read candidate for a computer.","Identify the LAPS deployment, exact attributes, encryption/decryptor controls, managed account and current password validity.","Limit password readers/decryptors to approved support roles, then follow the managed rotation process after a confirmed exposure.","Recollect readers and test approved recovery access and rotation without embedding password values in the report.","Deleting all recovery access or rotating an account without considering dependencies can interrupt support."});
guide.Add("ReadGMSAPassword|users",new string[]{"This concerns a managed service identity whose downstream privileges may be more important than its account name.","Confirm MSA versus gMSA, the host/reader mechanism, effective token, approved service hosts and downstream authorizations.","Narrow the unnecessary reader/host relationship and review the service identity privileges with the service owner.","Rescan the relevant descriptor or host relationship and confirm approved services can still obtain credentials and run.","Do not remove intended reader hosts or manipulate managed credentials without considering service continuity."});
guide.Add("DumpSMSAPassword|users",new string[]{"This concerns a managed service identity whose downstream privileges may be more important than its account name.","Confirm MSA versus gMSA, the host/reader mechanism, effective token, approved service hosts and downstream authorizations.","Narrow the unnecessary reader/host relationship and review the service identity privileges with the service owner.","Rescan the relevant descriptor or host relationship and confirm approved services can still obtain credentials and run.","Do not remove intended reader hosts or manipulate managed credentials without considering service continuity."});
guide.Add("AddMember|groups",new string[]{"Changing security-group membership can give a new member the privileges carried by this group.","Distinguish arbitrary membership management from self-membership, validate security-enabled state and review nested memberships and exact ACL scope.","Narrow unauthorized member-attribute or self-membership delegation at its actual source.","Rescan the group and nested paths and confirm the approved provisioning process still functions.","Changing a shared group or inherited delegation may affect many users and services."});
