namespace BH.Native
{
    public sealed class HelpEntry
    {
        public string Key,Category,Title,Summary,Body,Terms;
        public string[] Fields,Controls,Kinds;
        public HelpEntry(string key,string category,string title,string summary,string body,string terms,string[] fields,string[] controls,string[] kinds)
        {Key=key;Category=category;Title=title;Summary=summary;Body=body;Terms=terms;Fields=fields;Controls=controls;Kinds=kinds;}
        public override string ToString(){return Category+" · "+Title;}
        internal bool Matches(string query)
        {
            string haystack=Key+" "+Category+" "+Title+" "+Summary+" "+Body+" "+Terms+" "+string.Join(" ",Fields);
            foreach(string word in query.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries))if(haystack.IndexOf(word,StringComparison.OrdinalIgnoreCase)<0)return false;
            return true;
        }
    }
    public static class DesktopHelpCatalog
    {
        public static readonly Dictionary<string,HelpEntry> Topics=CreateTopics();
        private static Dictionary<string,HelpEntry> CreateTopics()
        {
            var topics=new Dictionary<string,HelpEntry>(StringComparer.OrdinalIgnoreCase);
            topics.Add("start",new HelpEntry("start","Using Tessera","Start here: read a finding or trace a path","Use Saved findings to review a recorded exposure candidate, Objects & relationships to inspect evidence, and Paths & graph to ask a directed reachability question.","What to check\r\nOpen the intended completed report. Inspect the source, target, relationship direction and collection window before considering a change.\r\n\r\nLimits and interpretation\r\nThe viewer reads a saved snapshot; it does not query AD or apply a recommendation. A candidate is a review lead, not confirmed compromise.","help introduction F1 glossary offline",new string[]{},new string[]{"HelpLibrary","Glossary","ToggleDetails"},new string[]{}));
topics.Add("paths",new HelpEntry("paths","Paths and graph","Source, target and path direction","An arrow runs from the principal with a modeled capability to the object it can affect. Find path returns the union of all equally short directed routes.","What to check\r\nEnter an exact name or identifier. DA resolves Domain Admins only when unambiguous. If a name matches several objects, choose its exact ID. Swap ends reverses the question and the waypoint order.\r\n\r\nLimits and interpretation\r\nA table in all-shortest mode is an edge set, not one sequential path. Longer detours are omitted. A domain-control capability may target the domain itself rather than the Domain Admins group.","DA Domain Admins target corp source target arrows reverse",new string[]{},new string[]{"SourceId","TargetId","FindPath","SwapEnds","PathSteps"},new string[]{}));
topics.Add("waypoints",new HelpEntry("waypoints","Paths and graph","Via 1 and Via 2","Waypoints require the route to visit specified objects in order: Source → Via 1 → Via 2 → Target. Blank waypoints are skipped.","What to check\r\nUse waypoints to test a proposed intermediate group or host. Read each leg's result when a leg fails or reaches a work limit.\r\n\r\nLimits and interpretation\r\nEach leg retains its shortest alternatives; the combined graph may revisit objects. This does not enumerate all possible simple paths.","",new string[]{},new string[]{"ViaOne","ViaTwo"},new string[]{}));
topics.Add("routes",new HelpEntry("routes","Paths and graph","Routes to target: shortest or all connections","Routes searches backwards from the target independently of the source and waypoint boxes.","What to check\r\nChoose Target: shortest for edges on shortest routes to the target. Choose all connections to include supported reverse-reachable detours and cycles.\r\n\r\nLimits and interpretation\r\nAll connections is not a count of attack scenarios or infinitely repeated cyclic walks. Dense administrator relationships can be expected context.","",new string[]{},new string[]{"TargetRoutes","RouteMode"},new string[]{}));
topics.Add("filters",new HelpEntry("filters","Paths and graph","Relationship filters","The checked relationship types determine which capabilities a path query can use.","What to check\r\nStart with all types, then narrow the question. Clear-all intentionally permits no relationship types. Check filters when an expected path disappears.\r\n\r\nLimits and interpretation\r\nA label being available in a filter does not mean that it was collected, derived or traversable in this snapshot. Inventory facts are not automatically control edges.","",new string[]{},new string[]{"PathFilters"},new string[]{}));
topics.Add("budgets",new HelpEntry("budgets","Paths and graph","Visit, time and display limits","Queries have independent work and display budgets. A visit is an identity examined, not a count of complete routes.","What to check\r\nRead the result status and any failed waypoint leg. Increase the visit budget or narrow the source/target if work stops early. Cancel stops the active local query.\r\n\r\nLimits and interpretation\r\nVisitLimit, SearchEdgeLimit, timeout, cancellation and a displayed edge limit are incomplete results, not evidence of no path. A bounded preview can be smaller than the stored graph.\r\n\r\nRelated properties\r\nLimited, StopReason, Visited, Processed, Pending, Status, MaxDepth","",new string[]{"Limited","StopReason","Visited","Processed","Pending","Status","MaxDepth"},new string[]{"VisitLimit","CancelQuery"},new string[]{}));
topics.Add("graph",new HelpEntry("graph","Paths and graph","Read a dense graph","Select a connection to list its individual relationship types; numbered curves identify parallel permissions. Select a row for the matching explanation.","What to check\r\nDrag to pan, use the mouse wheel or +/- to zoom, Fit to see the graph bounds, and Read for readable node labels. Previous/Next select nodes; Inspect opens their properties.\r\n\r\nLimits and interpretation\r\nA bundled connection can represent several relationships. Arrow direction matters. Expanding one connection does not discover additional directory facts.","",new string[]{},new string[]{"ZoomIn","ZoomOut","FitGraph","ReadPath","PreviousNode","NextNode","InspectGraphNode","AllGraphRelationships"},new string[]{}));
topics.Add("findings",new HelpEntry("findings","Review findings","Saved findings and priority","Saved findings retain representative shortest recorded chains from identities to the selected targets. Priority is a review-ranking heuristic.","What to check\r\nOpen the path, inspect each capability and its evidence, and validate the actual permissions and service prerequisites. Use on-demand path search for equally short alternatives.\r\n\r\nLimits and interpretation\r\nOne saved candidate is not every possible route. Membership-only context is not a new escalation finding. High priority is not an exploitation verdict or a CVSS score.\r\n\r\nRelated properties\r\nScore, Priority, Reasons, MissingObjects, TotalFindings","score high medium priority risk severity",new string[]{"Score","Priority","Reasons","MissingObjects","TotalFindings"},new string[]{"Findings","FindingSearch","SearchFindings","ResetFindings","OpenFinding","FindingObject"},new string[]{}));
topics.Add("paging",new HelpEntry("paging","Review findings","Pages, filters and report previews","The native viewer pages over saved candidates and collected objects; the HTML report includes bounded previews.","What to check\r\nUse the page controls and search the full native index when a name is absent from the HTML preview. Reset search fields if the result count seems unexpected.\r\n\r\nLimits and interpretation\r\nPage size, embedded preview size, search-work limits and total saved counts are different quantities. Empty filtered results do not establish an empty dataset.","",new string[]{},new string[]{"FindingPrevious","FindingNext","ObjectPrevious","ObjectNext","RelationshipNext"},new string[]{}));
topics.Add("objects",new HelpEntry("objects","Inspect evidence","Object search and navigation","Search matches names and identifiers in the selected index. Inspect shows the retained record and paged incoming or outgoing relationships.","What to check\r\nCheck the SID/GUID rather than relying only on a display name. Use Back/Forward to revisit inspected objects and Source/Target to populate a path query.\r\n\r\nLimits and interpretation\r\nA referenced identity may lack a collected object record. Missing properties may mean older data, unsupported collection or unreadable attributes; they are not automatically false.","",new string[]{},new string[]{"Objects","ObjectSearch","SearchObjects","ResetObjects","InspectObject","ObjectBack","ObjectForward","ObjectSource","ObjectTarget","Properties","PropertyHelp"},new string[]{}));
topics.Add("relationships",new HelpEntry("relationships","Inspect evidence","Incoming versus outgoing relationships","Incoming relationships describe what can affect the inspected object; outgoing relationships describe what that object can affect.","What to check\r\nChoose the direction and relationship filter, then select a row to inspect its evidence. Inspect other object follows the opposite endpoint.\r\n\r\nLimits and interpretation\r\nA relationship list includes inventory as well as capabilities. Graph relationship can display an inventory observation without making it part of control-path traversal.","",new string[]{},new string[]{"Direction","Relationships","LoadRelationships","ExplainRelationship","GraphRelationship","InspectOther"},new string[]{}));
topics.Add("continue",new HelpEntry("continue","Paths and graph","Continue a long recorded path","Long paths are displayed in segments so the interface stays usable. Continue loads the next segment from the indicated object.","What to check\r\nRead the shown step range and remaining hop count. Retain every segment if documenting the complete chain.\r\n\r\nLimits and interpretation\r\nA displayed or exported segment is not the whole path. Continued on-demand queries search from the continuation point using the selected supported relationships.\r\n\r\nRelated properties\r\nHopCount, PathLimited, NextPathId","",new string[]{"HopCount","PathLimited","NextPathId"},new string[]{"ContinuePath"},new string[]{}));
topics.Add("export",new HelpEntry("export","Review findings","Export a review plan","Export plan writes a local text explanation of the displayed relationships, their evidence, proposed remediation and validation steps.","What to check\r\nVerify source/target IDs, waypoint order, segment limits and coverage before sharing it. Tailor proposed changes to the real service owner.\r\n\r\nLimits and interpretation\r\nExporting does not validate a route or perform any AD change. The plan may describe a segment or route edge set rather than one linear chain.","",new string[]{},new string[]{"ExportPlan"},new string[]{}));
topics.Add("latest",new HelpEntry("latest","Collection and reports","Open latest and saved path rules","Open latest selects a completed report with a matching graph.sqlite. New application code and an old saved analysis can legitimately use different path-rule versions.","What to check\r\nReopen the updated scanner/viewer together. Regenerate the report from retained data when the saved rules differ. Confirm the full index path at the top of the viewer.\r\n\r\nLimits and interpretation\r\nRegenerating cannot add missing collection evidence. A new scan is needed for newly collected fields; it is not required merely to recalculate supported paths.\r\n\r\nRelated properties\r\nPathRules, CurrentPathRules","outdated latest graph.sqlite stale version package",new string[]{"PathRules","CurrentPathRules"},new string[]{},new string[]{}));
topics.Add("collection",new HelpEntry("collection","Collection and reports","Read-only collection and DC selection","Collection records directory objects, ACL observations and supported configuration using the selected identity. The DC picker uses available logon-DC information and cached domain-controller suggestions.","What to check\r\nConfirm the domain, selected DC, search scope, included OUs and worker status. An unavailable suggested DC should not be treated as a verified connection; use Connect to test access.\r\n\r\nLimits and interpretation\r\nRunning the launcher as an administrator does not demonstrate ordinary-user coverage. Endpoint/service checks may have separate permission requirements; a skipped or denied check leaves a gap.","logon DC cache domain controller LDAP connection permissions OU read only scanner",new string[]{},new string[]{},new string[]{}));
topics.Add("scope",new HelpEntry("scope","Collection and reports","Scope, missing data and no path","Coverage describes what the scanner could observe, resolve and model in the supplied collection window.","What to check\r\nCheck scan/merge metadata, worker failures, endpoint status, unreadable security descriptors, unresolved IDs, supported relationship kinds and current filters.\r\n\r\nLimits and interpretation\r\nNo path found means no route was found in the supported collected graph under this query's limits. It is not evidence that all attack paths are absent.","missing hidden broken no path coverage failed worker unresolved",new string[]{},new string[]{},new string[]{}));
topics.Add("merge",new HelpEntry("merge","Collection and reports","Merging scans and importing SharpHound","Merge deduplicates supported inventory and relationships; import maps supported SharpHound schema 5/6 records into Tessera's format.","What to check\r\nUse original consistent snapshots and comparable collection times. Review skipped object types, source collection status and conflict notes after import or merge.\r\n\r\nLimits and interpretation\r\nA merge does not make old facts simultaneous or improve permissions. Conflicting GPO, ownership or AD CS prerequisite snapshots suppress affected inferences. Azure/OpenGraph and many BloodHound derivations remain unsupported.","zip JSON schemas import merge duplicate conflict snapshot EnrichGroupTypes MaxGroupLookups EnrichmentSeconds read only LDAP group enrichment",new string[]{},new string[]{},new string[]{}));
topics.Add("analysis",new HelpEntry("analysis","Collection and reports","Quick, Deep, checkpoints and cancellation","Quick analysis uses configured depth/work budgets. Deep analysis can continue disk-backed discovery and save a checkpoint for a later resume.","What to check\r\nReview mode, selected targets, depth/visit/time limits, completion status and checkpoint location. Resume with the same inputs and compatible path rules.\r\n\r\nLimits and interpretation\r\nCompleted means the supported selected search frontier was exhausted. It does not mean full BloodHound parity or complete collection. A canceled/time-limited analysis can retain partial results.","quick deep checkpoint resume frontier cancel completed incomplete",new string[]{},new string[]{},new string[]{}));
topics.Add("changes",new HelpEntry("changes","Review findings","New, still observed and no longer observed","Snapshot comparison describes whether a modeled chain was observed in the supplied current and baseline data.","What to check\r\nCheck both collection windows, permissions, source scopes and rule versions before attributing a difference to a security change.\r\n\r\nLimits and interpretation\r\nNo longer observed can result from collection gaps or different inputs. It does not prove remediation. A newly observed path may have existed before the earlier collection.\r\n\r\nRelated properties\r\nObservation, AddedObjects, RemovedObjects, AddedRelationships, RemovedRelationships, UnchangedRelationships, NoLongerObserved","baseline delta comparison newly observed still observed no longer observed",new string[]{"Observation","AddedObjects","RemovedObjects","AddedRelationships","RemovedRelationships","UnchangedRelationships","NoLongerObserved"},new string[]{},new string[]{}));
topics.Add("assessment",new HelpEntry("assessment","Review findings","Supported, conditional, candidate and suppressed","These labels describe a model's evidence state. Supported/candidate means collected prerequisites match a supported rule; conditional means material context remains uncertain.","What to check\r\nRead the derivation-specific reason and witnesses. Suppressed relationships remain useful observations but are excluded from the affected automatic control projection.\r\n\r\nLimits and interpretation\r\nSupported never means full-token effective access or successful exploitation was tested. Raw/limited ownership observations and unsupported configurations must not be read as confirmed control.\r\n\r\nRelated properties\r\nAssessment, Reason, EffectiveAccessVerified, CertificateIssuanceVerified, ServerEnforcementVerified, EvidenceNote, PostExportGroupClassification","verified supported conditional suppressed candidate confidence",new string[]{"Assessment","Reason","EffectiveAccessVerified","CertificateIssuanceVerified","ServerEnforcementVerified","EvidenceNote","PostExportGroupClassification"},new string[]{},new string[]{}));
topics.Add("recommendations",new HelpEntry("recommendations","Review findings","Use remediation guidance safely","Recommendations identify which delegation, membership, configuration or administration practice to review; Tessera applies none of them.","What to check\r\nConfirm the business owner, preserve the original setting, narrow the actual unnecessary prerequisite, then rescan alternatives and test legitimate workflows. Use the saved original setting for a scoped rollback if needed.\r\n\r\nLimits and interpretation\r\nDo not remove a shared administrator group or reset credentials solely because it appears on a path. Expected administration, service dependencies and inheritance can explain many recorded relationships.","fix remediation recommendation rollback validation opsec operational impact",new string[]{},new string[]{},new string[]{}));
topics.Add("object:users",new HelpEntry("object:users","Object types","Users and service identities","A directory user can represent a person, service or managed service account.","What to check\r\nReview account state, security groups, delegated rights and observed sessions. Distinguish a gMSA/MSA from a conventional user by captured object classes and ownership context.\r\n\r\nLimits and interpretation\r\nA user object is not evidence of an active session, a known password or current authentication ability.","",new string[]{},new string[]{},new string[]{"users"}));
topics.Add("object:groups",new HelpEntry("object:groups","Object types","Security and distribution groups","Groups organize principals; security-enabled groups can contribute authorization SIDs to a token.","What to check\r\nCheck SecurityEnabled, nested memberships, membership-management rights and any downstream privileged access.\r\n\r\nLimits and interpretation\r\nA name such as Admins does not establish privilege. Unknown/distribution group state is insufficient for the derived membership rules that require a security token.","",new string[]{},new string[]{},new string[]{"groups"}));
topics.Add("object:computers",new HelpEntry("object:computers","Object types","Computer accounts and endpoint observations","A computer account is a directory identity for a device; endpoint access is separate evidence.","What to check\r\nReview Disabled/AccountStateKnown, SPNs, delegation, key credentials, local access observations and collection time.\r\n\r\nLimits and interpretation\r\nDirectory control is not the same as verified local administrator execution. Endpoint authorization and availability still matter.","",new string[]{},new string[]{},new string[]{"computers"}));
topics.Add("object:domains",new HelpEntry("object:domains","Object types","Domains and domain-root permissions","A domain is an AD security and naming boundary. Some capabilities such as DCSync and supported ESC1 candidates target the domain itself.","What to check\r\nReview domain-root ACLs, replication witnesses, trust inventory and captured policy context.\r\n\r\nLimits and interpretation\r\nA path ending at the domain need not pass through the Domain Admins group. Unmodeled trust relationships do not connect domains automatically.","",new string[]{},new string[]{},new string[]{"domains"}));
topics.Add("object:ous",new HelpEntry("object:ous","Object types","OUs and directory containers","Containers organize objects and may hold delegated ACLs or policy links.","What to check\r\nConfirm the actual object class and distinguished-name containment. Review inherited ACLs and supported GPO scope.\r\n\r\nLimits and interpretation\r\nContainment alone grants no control of a child. Not every container is an organizational unit or a valid GPO scope.","",new string[]{},new string[]{},new string[]{"ous"}));
topics.Add("object:gpos",new HelpEntry("object:gpos","Object types","Group Policy objects","A GPO has a directory object and policy content in SYSVOL, with separate edit, scope and client-processing conditions.","What to check\r\nReview GPO ACLs, link settings, filters, flags and supported computer scope; separately validate SYSVOL and effective policy.\r\n\r\nLimits and interpretation\r\nTessera's GPOAppliesTo model covers supported computer scope only. User/site/loopback policy and actual policy execution are not derived.","",new string[]{},new string[]{},new string[]{"gpos"}));
topics.Add("object:certtemplates",new HelpEntry("object:certtemplates","Object types","Certificate templates","Templates describe certificate purposes, naming, issuance requirements and enrollment permissions.","What to check\r\nUse the AD CS review and inspect the exact template's flags, purposes, approval/signatures, publication and enrollment grants.\r\n\r\nLimits and interpretation\r\nA matched template configuration alone does not establish ESC1 or certificate issuance.","",new string[]{},new string[]{},new string[]{"certtemplates"}));
topics.Add("object:enterprisecas",new HelpEntry("object:enterprisecas","Object types","Enterprise certificate authorities","An enterprise CA publishes templates and may issue certificates. Its directory object and CA service have different permission sources.","What to check\r\nCheck CAServicePermissionsCollected, imported service ACE summaries, HostingComputer, publication, certificate chain and target-domain trust.\r\n\r\nLimits and interpretation\r\nNative directory ACL inventory does not prove CA service enrollment or management. Supported ESC1 derivation currently requires imported direct-root evidence.","",new string[]{},new string[]{},new string[]{"enterprisecas"}));
topics.Add("object:rootcas",new HelpEntry("object:rootcas","Object types","Root CA trust objects","RootCA records describe configured directory trust anchors associated with a domain.","What to check\r\nCheck the captured DomainSid, certificate thumbprint and chain, and match them to the exact CA and target domain.\r\n\r\nLimits and interpretation\r\nA thumbprint match models collected trust inventory; it does not validate a live certificate, expiry, revocation or cryptographic signatures.","",new string[]{},new string[]{},new string[]{"rootcas"}));
topics.Add("object:aiacas",new HelpEntry("object:aiacas","Object types","Intermediate/AIA certificate authorities","AIA CA records preserve certificate authority inventory used by broader certificate-chain analysis.","What to check\r\nReview certificate identity and the complete ordered issuer chain against the target domain's configured trust.\r\n\r\nLimits and interpretation\r\nTessera does not yet derive intermediate-chain ESC paths. Presence in AIA alone does not establish domain authentication trust.","",new string[]{},new string[]{},new string[]{"aiacas"}));
topics.Add("object:ntauthstores",new HelpEntry("object:ntauthstores","Object types","NTAuth certificate stores","An NTAuthStore records CA certificate fingerprints designated for domain authentication trust.","What to check\r\nMatch its captured domain and certificate fingerprints to the exact publishing CA and RootCA evidence.\r\n\r\nLimits and interpretation\r\nNTAuth membership alone is insufficient for ESC1. Enrollment, template, trust-anchor and supported host prerequisites must also hold.","",new string[]{},new string[]{},new string[]{"ntauthstores"}));
topics.Add("object:issuancepolicies",new HelpEntry("object:issuancepolicies","Object types","Certificate issuance policies","Issuance-policy OIDs and optional linked groups provide context for certificate issuance and policy review.","What to check\r\nInspect the OID, linked group, template issuance-policy references and actual supported rule prerequisites.\r\n\r\nLimits and interpretation\r\nHasIssuancePolicy and OIDGroupLink are inventory; Tessera does not derive ESC13 group membership from them.","",new string[]{},new string[]{},new string[]{"issuancepolicies"}));
topics.Add("object:trusts",new HelpEntry("object:trusts","Object types","Domain trust inventory","A trust record describes direction, type, attributes and a remote-domain identity.","What to check\r\nInterpret direction from the source domain, validate the intended trust relationship, SID filtering and relevant server policy separately.\r\n\r\nLimits and interpretation\r\nTessera retains trust inventory but does not implement general effective trust traversal or every trust-based BloodHound edge.","",new string[]{},new string[]{},new string[]{"trusts"}));
topics.Add("object:sites",new HelpEntry("object:sites","Object types","AD sites","Sites describe directory topology and can influence service/DC selection and policy behavior.","What to check\r\nReview related servers and subnets, site configuration and the actual objects in scope.\r\n\r\nLimits and interpretation\r\nSite location alone is not a permission, session or endpoint connection. Site GPO applicability is outside the supported scope model.","",new string[]{},new string[]{},new string[]{"sites"}));
topics.Add("object:siteservers",new HelpEntry("object:siteservers","Object types","Directory site servers","A server object links directory site topology to a referenced computer.","What to check\r\nReview ServerReferenceDn and the parent site, resolving the actual computer before interpreting endpoint access.\r\n\r\nLimits and interpretation\r\nThe server inventory object is distinct from the running computer and from its local authorization.","",new string[]{},new string[]{},new string[]{"siteservers"}));
topics.Add("object:sitesubnets",new HelpEntry("object:sitesubnets","Object types","Directory site subnets","A subnet object associates a network range with an AD site.","What to check\r\nReview SiteDn and the configured subnet/site relationship with the directory owner.\r\n\r\nLimits and interpretation\r\nA configured subnet association does not prove current host placement, routing or a privilege relationship.","",new string[]{},new string[]{},new string[]{"sitesubnets"}));
topics.Add("object:external",new HelpEntry("object:external","Object types","Referenced or unresolved identities","Some SIDs, DNs, SPN hosts or foreign principals appear only as relationship endpoints.","What to check\r\nCollect or resolve the referenced object and confirm its stable identity before using names as evidence.\r\n\r\nLimits and interpretation\r\nMissing object details reduce confidence and can prevent path resolution. An unresolved reference is not a fabricated user or confirmed control path.","",new string[]{},new string[]{},new string[]{"external","?"}));
topics.Add("field:identity",new HelpEntry("field:identity","Object properties","IDs, names and directory location","Id is Tessera's stable graph identifier; Sid/Guid are captured directory identifiers, Dn is a directory location, and names are display/search aids.","What to check\r\nUse exact IDs for ambiguous names. A renamed object can keep its SID/GUID while its name or DN changes.\r\n\r\nLimits and interpretation\r\nA DN can move and a display name can be duplicated. Do not infer an object's permissions or class from its name.\r\n\r\nRelated properties\r\nId, Sid, Guid, Dn, Name, SamAccountName, TemplateName, TemplateAlias","",new string[]{"Id","Sid","Guid","Dn","Name","SamAccountName","TemplateName","TemplateAlias"},new string[]{},new string[]{}));
topics.Add("field:classes",new HelpEntry("field:classes","Object properties","Object class and directory type","ObjectClasses retains the directory schema classes. Some managed service identities require computer-derived ownership restrictions even when displayed under users.","What to check\r\nCheck the most specific captured class and derived-type context before interpreting attributes, containment or ownership.\r\n\r\nLimits and interpretation\r\nThe viewer's display bucket is not a complete schema classification. Unsupported or conflicting classes suppress some projections.\r\n\r\nRelated properties\r\nObjectClasses, GpoSomType, OwnershipComputerDerived","",new string[]{"ObjectClasses","GpoSomType","OwnershipComputerDerived"},new string[]{},new string[]{}));
topics.Add("field:state",new HelpEntry("field:state","Object properties","Enabled state and UAC","Disabled records the captured account state. AccountStateKnown distinguishes a readable account-control value from unavailable information; Uac is the underlying flag mask.","What to check\r\nInterpret individual flags and collection time. A null/missing state is unknown and must not be shown as enabled.\r\n\r\nLimits and interpretation\r\nEnabled does not prove successful logon, a valid credential, service reachability or absence of authentication restrictions.\r\n\r\nRelated properties\r\nDisabled, AccountStateKnown, Uac","",new string[]{"Disabled","AccountStateKnown","Uac"},new string[]{},new string[]{}));
topics.Add("field:host",new HelpEntry("field:host","Object properties","Host, DNS and service names","DNS and SPNs help associate services with computer identities; HostingComputer identifies the exact imported CA host. OS is a captured inventory description.","What to check\r\nResolve stable IDs and check aliases, duplicate SPNs and collection time. A CA's host evidence must qualify that same CA.\r\n\r\nLimits and interpretation\r\nAmbiguous host aliases are not resolved arbitrarily. A DNS/SPN name is not proof that a service is running or reachable.\r\n\r\nRelated properties\r\nDns, Os, Spns, HostingComputer, ServerReferenceDn, SiteDn","",new string[]{"Dns","Os","Spns","HostingComputer","ServerReferenceDn","SiteDn"},new string[]{},new string[]{}));
topics.Add("field:domain",new HelpEntry("field:domain","Object properties","Domain association","These identify the object's captured domain or a trust's remote domain; names and SIDs serve different roles.","What to check\r\nMatch domain SIDs when comparing CA/root/NTAuth or policy evidence. Verify which end of a trust is being described.\r\n\r\nLimits and interpretation\r\nDomain membership alone does not establish a usable trust path or cross-domain authorization.\r\n\r\nRelated properties\r\nDomainSid, DomainName, TargetDomainSid, FlatName","",new string[]{"DomainSid","DomainName","TargetDomainSid","FlatName"},new string[]{},new string[]{}));
topics.Add("field:group",new HelpEntry("field:group","Object properties","Security-enabled group state","True identifies a captured security group; false identifies a group that does not supply a security token for the relevant model. Missing means unknown.","What to check\r\nRead group type from current collection rather than assuming all imported groups are security-enabled.\r\n\r\nLimits and interpretation\r\nSeveral derived GPO, ownership, replication and ESC1 membership rules require a known security-enabled group. Older SharpHound exports may omit this fact.\r\n\r\nOptional import enrichment\r\nRead missing group types (import) uses the DC and identity from the connection tab. CLI: -ImportSharpHound -EnrichGroupTypes -Server <DC>. Only absent classifications are supplemented, by binary SID with returned objectSid/objectGUID and domain identity checks. Known values are preserved; failed, ambiguous and out-of-domain lookups remain unknown.\r\n\r\nEvidence times\r\nGroupTypeSource ReadOnlyLDAP identifies a post-export observation, with the DC, returned identity, groupType, read time and change markers retained. Original permissions and memberships are not revalidated. Such data does not make an old export a consistent live snapshot; affected candidates require current validation.\r\n\r\nOriginal import state\r\nGroupTypeImportState records Known, Missing or Malformed input classification. SecurityEnabledRaw preserves an invalid source value for inspection; it is not used as a Boolean. Optional LDAP enrichment supplements unknown state without modifying the original export.\r\n\r\nEnrichment result codes\r\nResolved means a verified exact-SID reply supplied a supported groupType. KnownInExport preserves an existing imported classification. OutsideSelectedDomain refuses a foreign or non-domain SID. Unavailable means connection/domain verification failed. NotFound, Ambiguous, MissingIdentity, IdentityMismatch, UnreadableGroupType, UnsupportedGroupType and LookupFailed leave state unknown. WorkLimit stops further lookups. uSNChanged and whenChanged are object change markers on the selected DC, not groupType-specific history or proof of replication convergence.\r\n\r\nRelated properties\r\nSecurityEnabled, GroupType, GroupTypeSource, GroupTypeServer, GroupTypeObservedUtc, GroupTypeObservedSid, GroupTypeObservedGuid, GroupTypeObservedDn, GroupTypeUsnChanged, GroupTypeWhenChanged, GroupTypeQueriedUtc, GroupTypeEnrichmentStatus, GroupTypeImportState, SecurityEnabledRaw","",new string[]{"SecurityEnabled","GroupType","GroupTypeSource","GroupTypeServer","GroupTypeObservedUtc","GroupTypeObservedSid","GroupTypeObservedGuid","GroupTypeObservedDn","GroupTypeUsnChanged","GroupTypeWhenChanged","GroupTypeQueriedUtc","GroupTypeEnrichmentStatus","GroupTypeImportState","SecurityEnabledRaw"},new string[]{},new string[]{}));
topics.Add("field:delegation",new HelpEntry("field:delegation","Object properties","Delegation flags","These flags describe account delegation configuration. Protocol transition and unconstrained delegation are different settings.","What to check\r\nCombine flags with exact allowed-service targets or resource-based delegation evidence, account restrictions and current authentication controls.\r\n\r\nLimits and interpretation\r\nA flag alone does not establish a currently usable delegation chain or successful impersonation.\r\n\r\nRelated properties\r\nProtocolTransition, UnconstrainedDelegation","",new string[]{"ProtocolTransition","UnconstrainedDelegation"},new string[]{},new string[]{}));
topics.Add("field:ownership",new HelpEntry("field:ownership","Object properties","Owner and OWNER RIGHTS context","OwnerSid identifies the captured owner. OWNER RIGHTS ACEs, applicable WRITE_DAC grants and relevant denies affect whether ownership is projected as control.","What to check\r\nRead the assessment and descriptor-analysis note; distinguish OwnsRaw/WriteOwnerRaw observations from supported or conditional projections.\r\n\r\nLimits and interpretation\r\nMissing descriptors, unsupported ACEs or relevant denies can suppress inference. OWNER RIGHTS being present does not mean the owner has unrestricted control.\r\n\r\nRelated properties\r\nOwnerSid, OwnerRightsPresent, OwnerRightsWriteDacl, OwnershipAnalysisKnown, OwnershipWriteDaclDeny, OwnershipNote, OwnershipMetadataVersion","",new string[]{"OwnerSid","OwnerRightsPresent","OwnerRightsWriteDacl","OwnershipAnalysisKnown","OwnershipWriteDaclDeny","OwnershipNote","OwnershipMetadataVersion"},new string[]{},new string[]{}));
topics.Add("field:ownerpolicy",new HelpEntry("field:ownerpolicy","Object properties","Captured ownership policy","Captured directory-policy context refines computer/MSA/gMSA ownership behavior: Allow, Block, Restricted, Default or Unknown.","What to check\r\nReview the exact mode, target type, same-domain administrator exception evidence and server-enforcement limitations in OWNERSHIP.md.\r\n\r\nLimits and interpretation\r\nDefault and Unknown are not explicit Allow. Restricted modes need operation-specific evaluation; cross-domain administrator exceptions are not fully modeled.\r\n\r\nRelated properties\r\nOwnerPolicyMode, OwnerDomainPolicyMode","",new string[]{"OwnerPolicyMode","OwnerDomainPolicyMode"},new string[]{},new string[]{}));
topics.Add("field:gpolink",new HelpEntry("field:gpolink","Object properties","GPO link and inheritance settings","Link options describe a policy link's enabled/enforced state. GpOptions captures scope inheritance configuration, not a permission grant.","What to check\r\nReview the link direction, actual scope class, parent chain, block inheritance and enforced links together.\r\n\r\nLimits and interpretation\r\nEnforced does not bypass every policy/security condition. GPLink inventory alone is not a traversable policy-control path.\r\n\r\nRelated properties\r\nLinkOptions, Enabled, Enforced, GpOptions, GpoLinkMetadataVersion","",new string[]{"LinkOptions","Enabled","Enforced","GpOptions","GpoLinkMetadataVersion"},new string[]{},new string[]{}));
topics.Add("field:gpoconfig",new HelpEntry("field:gpoconfig","Object properties","GPO settings and collection version","These capture policy enablement/version, directory-supported functionality, SYSVOL location and WMI filtering.","What to check\r\nValidate supported computer policy flags, no unresolved WMI filtering, and consistency of directory/SYSVOL versions before assessing practical effect.\r\n\r\nLimits and interpretation\r\nA SYSVOL path is a location, not proof of file write access. WMI/client processing, policy contents and resultant policy are not evaluated.\r\n\r\nRelated properties\r\nGpoFlags, GpoFunctionalityVersion, GpoFileSysPath, GpoVersionNumber, GpoWmiFilter, GpoMetadataVersion","",new string[]{"GpoFlags","GpoFunctionalityVersion","GpoFileSysPath","GpoVersionNumber","GpoWmiFilter","GpoMetadataVersion"},new string[]{},new string[]{}));
topics.Add("field:gposecurity",new HelpEntry("field:gposecurity","Object properties","GPO Read/Apply evidence","These summaries describe supported Read and Apply permissions from the collected GPO security descriptor.","What to check\r\nInspect the descriptor note and separate membership witnesses for the target computer's Read and Apply prerequisites.\r\n\r\nLimits and interpretation\r\nUnknown/unsupported ACLs, relevant denies or conflicting facts suppress modeled applicability. Summary arrays do not establish complete effective-token access.\r\n\r\nRelated properties\r\nGpoSecurityKnown, GpoSecurityNote, GpoReaders, GpoAppliers","",new string[]{"GpoSecurityKnown","GpoSecurityNote","GpoReaders","GpoAppliers"},new string[]{},new string[]{}));
topics.Add("field:template",new HelpEntry("field:template","Object properties","Certificate naming and issuance flags","Template naming and enrollment masks describe requester-supplied subject and approval behavior; signatures/schema affect issuance requirements. Flags on other object classes have class-specific meanings.","What to check\r\nUse the object's actual class. In the template review, subject bit 0x1 differs from SAN-only naming, approval uses bit 0x2, and schema 1 differs from later signature handling.\r\n\r\nLimits and interpretation\r\nDo not interpret a generic Flags value as a template flag mask on every class. Missing, malformed or future schema values remain unknown.\r\n\r\nRelated properties\r\nCertificateNameFlags, EnrollmentFlags, RequiredSignatures, SchemaVersion, Flags","",new string[]{"CertificateNameFlags","EnrollmentFlags","RequiredSignatures","SchemaVersion","Flags"},new string[]{},new string[]{}));
topics.Add("field:purposes",new HelpEntry("field:purposes","Object properties","Certificate purposes and policies","EKUs/application policies describe intended certificate purposes; issuance-policy OIDs and optional group links are distinct metadata.","What to check\r\nReview purpose restrictions, application-policy interactions and issuance requirements together with publication and enrollment rights.\r\n\r\nLimits and interpretation\r\nEmpty purpose lists may reflect missing/unreadable data and are not automatically unrestricted. An issuance-policy group link does not itself grant membership.\r\n\r\nRelated properties\r\nExtendedKeyUsage, ApplicationPolicies, IssuancePolicyOids, PolicyOid, LinkedGroupDn","",new string[]{"ExtendedKeyUsage","ApplicationPolicies","IssuancePolicyOids","PolicyOid","LinkedGroupDn"},new string[]{},new string[]{}));
topics.Add("field:caservice",new HelpEntry("field:caservice","Object properties","CA-service permissions and provenance","CA-service ACE summaries come from a successful supplied SharpHound CASecurity result. Directory-object ACEs are kept separately.","What to check\r\nCheck successful collection, failure text, right names, trustees and the exact CA identity. ESC1 requires service Enroll on the same publishing CA.\r\n\r\nLimits and interpretation\r\nDirectory Enroll/ManageCA observations cannot substitute for actual service evidence. A summarized allow ACE still needs full-token validation.\r\n\r\nRelated properties\r\nCAServicePermissionsCollected, CAServicePermissionsFailure, AdcsServiceAces, AdcsDirectoryAces","",new string[]{"CAServicePermissionsCollected","CAServicePermissionsFailure","AdcsServiceAces","AdcsDirectoryAces"},new string[]{},new string[]{}));
topics.Add("field:certtrust",new HelpEntry("field:certtrust","Object properties","Certificate chains and thumbprints","Thumbprints identify certificates in the collected inventory; CertChain is ordered, while NTAuth stores list trusted certificate identities.","What to check\r\nMatch CA, RootCA and NTAuth fingerprints in the same supported target-domain context; inspect the exact CA's host separately.\r\n\r\nLimits and interpretation\r\nCurrent ESC1 derivation supports imported direct-root chains only. A fingerprint is public identity metadata, not a private key or proof of current certificate validity.\r\n\r\nRelated properties\r\nCertChain, CertThumbprint, CertThumbprints","",new string[]{"CertChain","CertThumbprint","CertThumbprints"},new string[]{},new string[]{}));
topics.Add("field:adcsmeta",new HelpEntry("field:adcsmeta","Object properties","AD CS capture state and denies","These retain the source/schema marker, reported deny counts and explicit imported template prerequisites used by supported AD CS rules.","What to check\r\nDistinguish a captured false value from an omitted property. Review contradiction/conflict notes and original exported records.\r\n\r\nLimits and interpretation\r\nVersion/source markers describe the parser's evidence shape; they do not attest that current CA or domain authentication enforcement was tested.\r\n\r\nRelated properties\r\nAdcsMetadataVersion, AdcsMetadataSource, AdcsExplicitDenyCount, AdcsInheritedDenyCount, AdcsRequiresManagerApproval, AdcsEnrolleeSuppliesSubject, AdcsAuthenticationEnabled","",new string[]{"AdcsMetadataVersion","AdcsMetadataSource","AdcsExplicitDenyCount","AdcsInheritedDenyCount","AdcsRequiresManagerApproval","AdcsEnrolleeSuppliesSubject","AdcsAuthenticationEnabled"},new string[]{},new string[]{}));
topics.Add("field:publication",new HelpEntry("field:publication","Object properties","Published certificate templates","The CA directory object lists which templates it publishes. Imported publication is also retained as a template-to-CA observation.","What to check\r\nMatch the template's stable identity or validated alias to the exact publishing CA.\r\n\r\nLimits and interpretation\r\nPublication does not grant enrollment and does not establish that requests will be issued.\r\n\r\nRelated properties\r\nPublishedTemplates","",new string[]{"PublishedTemplates"},new string[]{},new string[]{}));
topics.Add("field:trust",new HelpEntry("field:trust","Object properties","Trust direction, type and attributes","These are raw directory trust configuration values and flags describing the recorded trust object.","What to check\r\nInterpret direction relative to the source domain and validate the relevant forest/domain policy and SID filtering separately.\r\n\r\nLimits and interpretation\r\nTessera does not translate these fields into complete trust-based privilege traversal. A trust inventory row alone is not an attack path.\r\n\r\nRelated properties\r\nTrustDirection, TrustType, TrustAttributes","",new string[]{"TrustDirection","TrustType","TrustAttributes"},new string[]{},new string[]{}));
topics.Add("field:edge",new HelpEntry("field:edge","Object properties","Relationship endpoints and evidence source","Source/Target describe the directed relationship; endpoint DN flags indicate identities needing resolution. Derivation names a modeled projection, while EvidenceSource/Authority identify provenance.","What to check\r\nRead the relationship type and its source-specific explanation. Match stable endpoints and verify whether the evidence is directory, endpoint, service, imported or derived.\r\n\r\nLimits and interpretation\r\nA relationship label can appear in inventory without being traversable. Verified-source flags do not establish full-token effective access or successful execution.\r\n\r\nRelated properties\r\nSource, Target, EdgeType, SourceIsDn, TargetIsDn, Derivation, EvidenceSource, Authority, ServicePermissionVerified","",new string[]{"Source","Target","EdgeType","SourceIsDn","TargetIsDn","Derivation","EvidenceSource","Authority","ServicePermissionVerified"},new string[]{},new string[]{}));
topics.Add("field:ace",new HelpEntry("field:ace","Object properties","Captured ACE summaries","An ACE summary identifies a trustee, a classified right, reported allow/deny context and inheritance state.","What to check\r\nInspect the original descriptor/source when exact applicability matters. Locate the ancestor where an inherited grant originates rather than editing an unrelated explicit ACE.\r\n\r\nLimits and interpretation\r\nA summary is not a complete effective-access calculation. Inherit-only, object class/property GUIDs, denies and group token conditions can change applicability.\r\n\r\nRelated properties\r\nPrincipalSID, PrincipalType, RightName, AccessType, IsInherited","",new string[]{"PrincipalSID","PrincipalType","RightName","AccessType","IsInherited"},new string[]{},new string[]{}));
topics.Add("field:conflicts",new HelpEntry("field:conflicts","Object properties","Conflicting captured evidence","A conflict marker records incompatible prerequisite facts across supplied snapshots and survives supported merge round trips.","What to check\r\nReturn to the original scan folders, compare collection times/scope and collect a consistent current snapshot where needed.\r\n\r\nLimits and interpretation\r\nMerging does not justify selecting only the most permissive value. A conflict can suppress a projection without proving that the real capability is denied.\r\n\r\nRelated properties\r\nAdcsEvidenceConflict, OwnershipEvidenceConflict, GpoEvidenceConflict, GpoLinkEvidenceConflict","",new string[]{"AdcsEvidenceConflict","OwnershipEvidenceConflict","GpoEvidenceConflict","GpoLinkEvidenceConflict"},new string[]{},new string[]{}));
topics.Add("field:witness",new HelpEntry("field:witness","Object properties","Membership and scope witnesses","A witness records a supporting chain of captured facts used by a derivation, rather than the complete effective token or every possible route.","What to check\r\nFollow each chain from the source toward its grant trustee or scope root. DCSync, GPO and ESC1 can require distinct prerequisites reached through different memberships. Confirm that all witnesses refer to the same modeled target and supported rule.\r\n\r\nLimits and interpretation\r\nWitness arrays are bounded previews, generally up to 64 objects. A preview can omit later entries; consult the graph and collection data for the full chain. A witness is not evidence that an operation succeeded or that deny rules were fully evaluated.\r\n\r\nRelated properties\r\nGetChangesMembership, GetChangesAllMembership, TemplateMembership, CAServiceMembership, ReadMembership, ApplyMembership, ContainmentChain, AdminMembership, WitnessLimited","",new string[]{"GetChangesMembership","GetChangesAllMembership","TemplateMembership","CAServiceMembership","ReadMembership","ApplyMembership","ContainmentChain","AdminMembership","WitnessLimited"},new string[]{},new string[]{}));
topics.Add("field:composition",new HelpEntry("field:composition","Object properties","Derived-rule identities and grant provenance","These fields identify which exact template, CA, trust objects, scope root or grant trustee supplied the modeled prerequisites.","What to check\r\nMatch stable IDs to the inspected objects. ESC1 uses the same publishing CA for template and service enrollment, with root and NTAuth trust in the same target domain. GPO LinkRoot and ownership PolicySource describe different rule-specific context.\r\n\r\nLimits and interpretation\r\nOne derived edge can retain one representative qualifying composition; Tessera does not expand every alternate CA/template composition. Grant provenance and captured policy are modeling evidence, not live execution or complete effective access.\r\n\r\nRelated properties\r\nTemplate, EnterpriseCA, RootCA, NTAuthStore, TemplateGrant, CAServiceGrant, TemplateRight, CAServiceRight, LinkRoot, PolicySource","",new string[]{"Template","EnterpriseCA","RootCA","NTAuthStore","TemplateGrant","CAServiceGrant","TemplateRight","CAServiceRight","LinkRoot","PolicySource"},new string[]{},new string[]{}));
topics.Add("unsupported",new HelpEntry("unsupported","Collection and reports","Unsupported BloodHound features and unfamiliar labels","Help coverage is separate from collection and path-rule support. Tessera does not implement every BloodHound relationship, derivation, platform or query.","What to check\r\nRead PATH-PARITY.md and the GPO, ownership and AD CS scope notes for current prerequisites and limits. Check the actual imported bucket, derivation, identity resolution and query filters before expecting a relationship to participate in a route.\r\n\r\nLimits and interpretation\r\nAn imported unfamiliar label may be preserved as inventory without being traversed. Adding help or selecting a glossary entry does not enable that capability. Consult the original BloodHound documentation for features outside the supported model.","GoldenCert CoerceToTGT SyncLAPSPassword ADCSESC3 ADCSESC4 ADCSESC6a ADCSESC6b ADCSESC9a ADCSESC9b ADCSESC10a ADCSESC10b ADCSESC13 ADCSESC16 HasTrustKeys SameForestTrust ProtectAdminGroups Azure OpenGraph CoerceAndRelayNTLMToSMB CoerceAndRelayNTLMToADCS CoerceAndRelayNTLMToADCSRPC CoerceAndRelayNTLMToLDAP CoerceAndRelayNTLMToLDAPS WriteAltSecurityIdentities WritePublicInformation ServerIs DCFor SpoofSIDHistory AbuseTGTDelegation SyncedToADUser",new string[]{},new string[]{},new string[]{}));
            return topics;
        }
        public static HelpEntry ForField(string name){foreach(var item in Topics.Values)foreach(string value in item.Fields)if(string.Equals(name,value,StringComparison.OrdinalIgnoreCase))return item;return null;}
        public static HelpEntry ForKind(string name){foreach(var item in Topics.Values)foreach(string value in item.Kinds)if(string.Equals(name,value,StringComparison.OrdinalIgnoreCase))return item;return null;}
        public static HelpEntry ForControl(string name){foreach(var item in Topics.Values)foreach(string value in item.Controls)if(string.Equals(name,value,StringComparison.OrdinalIgnoreCase))return item;return null;}
        public static string Describe(HelpEntry topic)
        {return topic==null?"This property has no built-in interpretation. Read the original source and collection notes; do not infer effective access from an unfamiliar value.":topic.Summary+"\r\n\r\n"+topic.Body;}
        public static List<HelpEntry> Search(string query)
        {
            query=(query??"").Trim();var result=new List<HelpEntry>();HelpEntry exact;
            if(Topics.TryGetValue(query,out exact)){result.Add(exact);return result;}
            exact=ForField(query);if(exact!=null){result.Add(exact);return result;}
            foreach(var topic in Topics.Values)if(topic.Matches(query))result.Add(topic);
            foreach(var pair in DesktopViewer.Guide)
            {
                string body=DesktopViewer.Explain(ViewerJson.Map("ty",pair.Key,"sn","Source principal","tn","Target object"));
                var topic=new HelpEntry("relationship:"+pair.Key,"Relationships",pair.Key+" — "+pair.Value[0],pair.Value[1],
                    "General reference: this help entry is not evidence that the relationship was collected or that a path exists.\r\n\r\n"+body,"",new string[0],new string[0],new string[0]);
                if(topic.Matches(query))result.Add(topic);
            }
            result.Sort(delegate(HelpEntry a,HelpEntry b){if(a.Key=="start")return b.Key=="start"?0:-1;if(b.Key=="start")return 1;int order=string.Compare(a.Category,b.Category,StringComparison.OrdinalIgnoreCase);return order!=0?order:string.Compare(a.Title,b.Title,StringComparison.OrdinalIgnoreCase);});
            return result;
        }
    }
    public sealed class HelpLibraryWindow : Form
    {
        private readonly TextBox search;
        private readonly ListBox choices;
        private readonly RichTextBox content;
        private readonly Label count;
        public HelpLibraryWindow(string initialQuery)
        {
            Text="Tessera help & glossary | offline";Name="HelpLibraryWindow";Size=new Size(1050,720);MinimumSize=new Size(800,540);StartPosition=FormStartPosition.CenterParent;
            Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(12,18,32);ForeColor=Color.FromArgb(237,243,252);
            var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(12)};
            layout.RowStyles.Add(new RowStyle(SizeType.Absolute,38));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,30));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(layout);
            search=new TextBox{Name="HelpSearch",Dock=DockStyle.Fill,BackColor=Color.FromArgb(19,30,48),ForeColor=ForeColor};search.AccessibleName="Search help topics, fields or relationships";layout.Controls.Add(search,0,0);
            count=new Label{Name="HelpCount",Dock=DockStyle.Fill,ForeColor=Color.FromArgb(164,180,202),TextAlign=ContentAlignment.MiddleLeft};layout.Controls.Add(count,0,1);
            var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1000,600),SplitterDistance=350,Panel1MinSize=230,Panel2MinSize=370,SplitterWidth=8};layout.Controls.Add(split,0,2);
            choices=new ListBox{Name="HelpTopics",Dock=DockStyle.Fill,BackColor=Color.FromArgb(19,30,48),ForeColor=ForeColor,BorderStyle=BorderStyle.None,HorizontalScrollbar=true,IntegralHeight=false};split.Panel1.Controls.Add(choices);
            content=new RichTextBox{Name="HelpTopicText",Dock=DockStyle.Fill,ReadOnly=true,BackColor=Color.FromArgb(19,30,48),ForeColor=ForeColor,BorderStyle=BorderStyle.None,DetectUrls=false};split.Panel2.Controls.Add(content);
            search.TextChanged+=delegate{UpdateTopics();};choices.SelectedIndexChanged+=delegate{var item=choices.SelectedItem as HelpEntry;content.Text=item==null?"Choose a topic to read its meaning, checks and limitations.":item.Title+"\r\n\r\n"+DesktopHelpCatalog.Describe(item);content.Select(0,0);content.ScrollToCaret();};
            KeyPreview=true;KeyDown+=delegate(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Escape){Close();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.F){search.Focus();search.SelectAll();e.SuppressKeyPress=true;}};
            search.Text=initialQuery??"";UpdateTopics();Shown+=delegate{search.Focus();search.SelectAll();};
        }
        private void UpdateTopics()
        {
            choices.BeginUpdate();try{choices.Items.Clear();foreach(var topic in DesktopHelpCatalog.Search(search.Text))choices.Items.Add(topic);}finally{choices.EndUpdate();}
            count.Text=choices.Items.Count+" matching entries · Ctrl+F to search · Escape to close";
            if(choices.Items.Count>0)choices.SelectedIndex=0;else content.Text="No matching help. Try a relationship label, property name such as SecurityEnabled, or a task such as routes or import. No behavior is inferred from an unfamiliar label.";
        }
    }
